local mbm_files = {}
mbm_files.assignments = function(...)
-- Mod Bindings Menu's assignments file and reservations: the native action of
-- each automatic binding, kept for its id across sessions and saved safely.
-- src/mod_bindings_menu.lua runs this file once as mbm_files.assignments(mbm);
-- it adds load_assignments, flush_assignments and assign_action to mbm.
local mbm = ...
local bit = require('bit')
local state, note = mbm.state, mbm.note
local DORMANT_ACTIONS, SLOTS, ASSIGNMENTS_FILE = mbm.DORMANT_ACTIONS, mbm.SLOTS, mbm.ASSIGNMENTS_FILE

-- The path of one of Mod Bindings Menu's settings files, in the loader's log
-- folder, or nil without one.
local function settings_path(name)
    local loader_api = rawget(_G, 'CowboyBingusModLoader')
    local directory = type(loader_api) == 'table' and loader_api.log_directory
    if type(directory) ~= 'string' or directory == '' then
        local local_app_data = os.getenv('LOCALAPPDATA')
        if not local_app_data then return nil end
        directory = local_app_data .. '/CowboyBingus/Helldivers2'
    end
    return directory .. '/' .. name
end
local function assignments_path() return settings_path(ASSIGNMENTS_FILE) end

-- Automatic bindings keep their native action across sessions, because the
-- game saves each action's keys under the action's name. The assignments file,
-- format 2, holds one record per line:
--   format 2
--   session <n>                         the number of the last session that
--                                       counted (see count_session)
--   <id>\t<group>\t<action>\t<seen>     an automatic binding and the last
--                                       session it registered in
--   action <group>:<action> cleared <session> found <hash> left <hash>
--                                       the sweep cleared the action's inherited
--                                       developer defaults in that session: the
--                                       fingerprints of the list it found and of
--                                       the list it last left (src/sweep.lua)
--   action <group>:<action> clear       handed over from an expired binding:
--                                       to be cleared entirely
--   slot <slot> <seen> <id>             the owner of a shared fixed slot (slot 2,
--                                       the v1 third-party slot) and the last
--                                       session it registered in (v2.3)
--   end                                 a complete file always ends with it
-- v2.1 wrote only "<id>\t<group>\t<action>" lines. v2.2.1 and older ignore
-- slot lines and drop them at their next save.
local function new_book()
    return {bindings = {}, holders = {}, actions = {}, owners = {}, saved = 0, counted = false, dirty = false,
            failed = false, retry = 0, damaged = false}
end

-- A binding read from the file: bindings = {[id] = {code, seen}} and
-- holders = {[code] = id}. An action held twice keeps its latest binding.
local function read_binding(book, id, code, seen)
    if not state.auto_codes[code] then return end
    local holder = book.holders[code]
    local other = holder and book.bindings[holder]
    if other and (other.seen or 0) >= (seen or 0) then return end
    if other then book.bindings[holder] = nil end
    local before = book.bindings[id]
    if before and book.holders[before.code] == id then book.holders[before.code] = nil end
    book.bindings[id], book.holders[code] = {code = code, seen = seen}, id
end

-- An action record: {cleared = session, found = fingerprint, left = fingerprint}
-- or {clear = true}, for dormant actions only.
local function read_action(book, code, record)
    if not state.code_order[code] then return end
    if record == 'clear' then
        book.actions[code] = {clear = true}
        return
    end
    local cleared, found, left = record:match('^cleared (%d+) found (%x+) left (%x+)$')
    if cleared then
        book.actions[code] = {cleared = tonumber(cleared), found = bit.tobit(tonumber(found, 16)),
                              left = bit.tobit(tonumber(left, 16))}
    end
end

-- A shared slot's owner: {id, seen}, for the slots in SHARED_SLOTS only.
local SHARED_SLOTS = {[2] = true}
local function read_owner(book, slot, seen, id)
    if SHARED_SLOTS[slot] then book.owners[slot] = {id = id, seen = seen} end
end

local function read_line(book, line)
    local id, group, action, seen = line:match('^([^\t]+)\t(%d+)\t(%d+)\t?(%d*)$')
    if id then return read_binding(book, id, tonumber(group) * 65536 + tonumber(action), tonumber(seen)) end
    group, action, seen = line:match('^action (%d+):(%d+) (.+)$')
    if group then return read_action(book, tonumber(group) * 65536 + tonumber(action), seen) end
    local slot, owner_seen, owner = line:match('^slot (%d+) (%d+) ([^\t]+)$')
    if slot then return read_owner(book, tonumber(slot), tonumber(owner_seen), owner) end
    if line == 'end' then
        book.complete = true
        return
    end
    local key, value = line:match('^(%a+) (%d+)$')
    if key == 'format' then book.format = tonumber(value)
    elseif key == 'session' then book.saved = tonumber(value) end
end

-- The assignments in text, or nil when a format 2 file was cut short. v2.1
-- bindings count as last seen in the session that saved the file.
local function parse_assignments(text)
    local book = new_book()
    for line in text:gmatch('[^\r\n]+') do read_line(book, line) end
    if book.format and not book.complete then return nil end
    for _, binding in pairs(book.bindings) do binding.seen = binding.seen or book.saved end
    return book
end

local function file_exists(path)
    local file = io.open(path, 'rb')
    if not file then return false end
    file:close()
    return true
end

-- The assignments in the file at path, or nil when it is missing, empty or
-- cut short. book.text keeps the file's text.
local function read_assignments(path)
    local file = io.open(path, 'rb')
    if not file then return nil end
    local text = file:read('*a')
    file:close()
    if not text or text == '' then return nil end
    local book = parse_assignments(text)
    if book then book.text = text end
    return book
end

-- The backup, for a file that is missing (a save interrupted between its
-- renames leaves only the backup) or unusable. It is written back at the next
-- save, without touching the good backup.
local function restore_assignments(path)
    local damaged = file_exists(path)
    local book = read_assignments(path .. '.bak')
    if book then
        book.text, book.dirty, book.damaged = nil, true, damaged
        note('Binding assignments restored from ' .. ASSIGNMENTS_FILE .. '.bak; the file was ' ..
             (damaged and 'damaged.' or 'missing.'))
        return book
    end
    if damaged then note('The binding assignments file is damaged and has no backup; automatic bindings start over.') end
    return nil
end

-- Loads the assignments once per session, which gets the next session number.
-- state.assignments = {bindings, holders, actions, session = this session's
-- number, saved = the number in the file, counted = this session counts,
-- text = the file as read or last written, dirty = unsaved changes, failed =
-- the last save failed (logged once), retry = seconds before the next attempt,
-- damaged = only the backup is usable}.
local function load_assignments()
    if state.assignments then return state.assignments end
    local path = assignments_path()
    local book = path and (read_assignments(path) or restore_assignments(path)) or new_book()
    book.session = book.saved + 1
    state.assignments = book
    return book
end

-- A session counts towards the expiry of reservations from the first time a
-- mod asks for an automatic binding in it, whether it gets one or not: a mod
-- refused for the reservations of mods that are gone must see them expire. Its
-- number is saved only then, and only a session whose bindings work saves, so
-- launches without such mods (test runs included) and sessions on an
-- unsupported game build never age a reservation.
local function count_session(book)
    if book.counted then return end
    book.counted, book.dirty = true, true
end

local function action_line(code, action)
    local name = 'action ' .. math.floor(code / 65536) .. ':' .. code % 65536
    if action.clear then return name .. ' clear' end
    return name .. ' cleared ' .. action.cleared .. ' found ' .. bit.tohex(action.found) .. ' left ' ..
           bit.tohex(action.left)
end

local function assignments_text(book)
    local lines = {}
    for id, binding in pairs(book.bindings) do
        lines[#lines + 1] = id .. '\t' .. math.floor(binding.code / 65536) .. '\t' .. binding.code % 65536 ..
                            '\t' .. binding.seen
    end
    table.sort(lines)
    table.insert(lines, 1, 'format 2')
    table.insert(lines, 2, 'session ' .. (book.counted and book.session or book.saved))
    for _, entry in ipairs(DORMANT_ACTIONS) do
        local code = entry[1] * 65536 + entry[2]
        if book.actions[code] then lines[#lines + 1] = action_line(code, book.actions[code]) end
    end
    for slot = 1, SLOTS do
        local owner = book.owners[slot]
        if owner then lines[#lines + 1] = 'slot ' .. slot .. ' ' .. owner.seen .. ' ' .. owner.id end
    end
    lines[#lines + 1] = 'end'
    return table.concat(lines, '\n') .. '\n'
end

-- Moves the current file out of the way: to the backup, or deleted when it is
-- damaged (the backup then holds the good copy). True when path is free.
local function set_aside(path, backup, damaged)
    if not file_exists(path) then return true end
    if damaged then return os.remove(path) end
    os.remove(backup)
    return os.rename(path, backup)
end

-- Writes text to path through <path>.tmp, every write and the close checked;
-- the old file becomes <path>.bak, then the new one is renamed into place.
-- Returns true, or false and the reason; on failure the old file stays.
local function replace_file(path, text, damaged)
    local temporary, backup = path .. '.tmp', path .. '.bak'
    local file, problem = io.open(temporary, 'wb')
    if not file then return false, problem end
    local written, write_problem = file:write(text)
    local closed, close_problem = file:close()
    if not (written and closed) then
        os.remove(temporary)
        return false, write_problem or close_problem
    end
    local moved, move_problem = set_aside(path, backup, damaged)
    if not moved then
        os.remove(temporary)
        return false, move_problem
    end
    local placed, place_problem = os.rename(temporary, path)
    if placed then return true end
    if not damaged then os.rename(backup, path) end
    os.remove(temporary)
    return false, place_problem
end

local SAVE_RETRY = 60 -- seconds before a failed save is tried again
-- Saves changed assignments, from the step (never inside another mod's call).
-- Unchanged assignments are not written. A failed save keeps them dirty, logs
-- once and is tried again SAVE_RETRY seconds later.
local function flush_assignments(seconds)
    local book = state.assignments
    if book.retry > 0 then
        book.retry = book.retry - seconds
        return
    end
    local text, path = assignments_text(book), assignments_path()
    local saved, problem = text == book.text, 'no settings folder'
    if not saved and path then saved, problem = replace_file(path, text, book.damaged) end
    if saved then
        if book.failed then note('Saved binding assignments after an earlier failure.') end
        book.text, book.dirty, book.failed, book.damaged = text, false, false, false
        return
    end
    book.retry = SAVE_RETRY
    if book.failed then return end
    book.failed = true
    note('Cannot save binding assignments (' .. tostring(problem) .. '); keeping them and trying again in ' ..
         SAVE_RETRY .. ' seconds.')
end

-- Reservations. An automatic action stays reserved for its binding id across
-- sessions, also in a session where the id registers late or not at all, until
-- the id has not registered for EXPIRY_SESSIONS sessions that count (see
-- count_session). A new id takes a free action, else the action of the
-- binding absent longest once its reservation has ended (its keys are then
-- cleared); else registration fails with a reason.
local EXPIRY_SESSIONS = 30
local AUTO_ACTIONS = #DORMANT_ACTIONS - SLOTS
local REASON_RESERVED = 'no free binding action; the others are reserved by mods not loaded this session'
local REASON_FULL = 'all ' .. AUTO_ACTIONS .. ' automatic binding actions in use'

local function auto_code(index)
    return DORMANT_ACTIONS[index][1] * 65536 + DORMANT_ACTIONS[index][2]
end

-- Whether the binding missed its last EXPIRY_SESSIONS sessions (this one,
-- still running, does not count).
local function expired(book, binding)
    return book.session - binding.seen - 1 >= EXPIRY_SESSIONS
end

-- The first automatic action that no binding holds and none uses.
local function free_action(book)
    for index = SLOTS + 1, #DORMANT_ACTIONS do
        local code = auto_code(index)
        if not state.used[code] and not book.holders[code] then return code end
    end
    return nil
end

-- The action of the binding absent longest, once its reservation has ended.
local function expired_action(book)
    local oldest, oldest_seen
    for index = SLOTS + 1, #DORMANT_ACTIONS do
        local code = auto_code(index)
        local holder = book.holders[code]
        local binding = holder and book.bindings[holder]
        if binding and not state.used[code] and expired(book, binding)
           and (not oldest or binding.seen < oldest_seen) then
            oldest, oldest_seen = code, binding.seen
        end
    end
    return oldest
end

-- Gives code to id. An expired binding that held it loses it, and its keys are
-- cleared so they do not carry over to the new binding.
local function hand_over(book, id, code)
    local previous = book.holders[code]
    if previous then
        note('Native action ' .. math.floor(code / 65536) .. ':' .. code % 65536 .. ' goes to ' .. id .. ': ' ..
             previous .. ' has not registered for ' .. (book.session - book.bindings[previous].seen - 1) ..
             ' sessions; its keys are cleared.')
        book.bindings[previous] = nil
        book.actions[code] = {clear = true}
    end
    local own = book.bindings[id]
    if own and book.holders[own.code] == id then book.holders[own.code] = nil end
    book.bindings[id], book.holders[code] = {code = code, seen = book.session}, id
    book.dirty = true
    return code
end

-- Why no action is left: reservations of mods not loaded this session, or
-- every automatic action in use. Logged once per id, unless quiet (the
-- registration falls back to an extended binding instead).
local function refuse(book, id, quiet)
    local reason = REASON_FULL
    for index = SLOTS + 1, #DORMANT_ACTIONS do
        local code = auto_code(index)
        if not state.used[code] and book.holders[code] then reason = REASON_RESERVED end
    end
    if not quiet and not state.refused[id] then
        state.refused[id] = true
        note('Cannot register ' .. id .. ': ' .. reason .. '.')
    end
    return reason
end

-- The automatic action for id, or nil and the reason (see refuse for quiet).
local function assign_action(id, quiet)
    local book = load_assignments()
    count_session(book)
    local own = book.bindings[id]
    if own and not state.used[own.code] then
        if own.seen ~= book.session then own.seen, book.dirty = book.session, true end
        return own.code
    end
    local code = free_action(book) or expired_action(book)
    if code then return hand_over(book, id, code) end
    return nil, refuse(book, id, quiet)
end

-- The native action for a request of a shared fixed slot (slot 2), or nil and
-- the reason. The slot's action, and the keys the game saved on it, belong to
-- one id across sessions, whatever order the mods load in: its owner, saved in
-- the assignments file. v2.2.1 and older gave the slot to the first caller of
-- each session, so reversing two v1.1 mods moved both, and one inherited the
-- other's keys (the 2026-10-13 plan audit).
-- - The owner gets the slot's action, also in a session where it registers late.
-- - An id with an automatic reservation keeps it. Files written before owners
--   were saved have none; such a reservation shows the id was the one moved.
-- - Any other id, while the owner's reservation lasts, gets an automatic action.
-- - With no owner, or one that has not registered for EXPIRY_SESSIONS sessions
--   that count, the caller becomes the owner, and the expired owner's keys are
--   cleared so they do not carry over.
-- A shared-slot request counts its session, as an automatic request does.
local function assign_shared(id, slot, fixed_code, quiet)
    local book = load_assignments()
    count_session(book)
    local owner = book.owners[slot]
    if owner and owner.id == id and not state.used[fixed_code] then
        if owner.seen ~= book.session then owner.seen, book.dirty = book.session, true end
        return fixed_code
    end
    if book.bindings[id] or state.used[fixed_code] or owner and owner.id ~= id and not expired(book, owner) then
        return assign_action(id, quiet)
    end
    if owner and owner.id ~= id then
        note('Slot ' .. slot .. ' goes to ' .. id .. ': ' .. owner.id .. ' has not registered for ' ..
             (book.session - owner.seen - 1) .. ' sessions; its keys are cleared.')
        book.actions[fixed_code] = {clear = true}
    end
    book.owners[slot], book.dirty = {id = id, seen = book.session}, true
    return fixed_code
end

mbm.load_assignments, mbm.flush_assignments, mbm.assign_action = load_assignments, flush_assignments, assign_action
mbm.assign_shared, mbm.SHARED_SLOTS = assign_shared, SHARED_SLOTS
mbm.POOL_REASONS = {[REASON_RESERVED] = true, [REASON_FULL] = true}
-- Whether id holds an automatic reservation (kept native, never extended).
function mbm.reserved(id) return load_assignments().bindings[id] ~= nil end
-- Shared with the extended bindings' file (src/extended_store.lua).
mbm.settings_path, mbm.replace_file, mbm.file_exists, mbm.SAVE_RETRY = settings_path, replace_file, file_exists, SAVE_RETRY
end
mbm_files.bingus_memory = function(...)
-- bingus_memory.lua, version 1: the read side of Bingus Shared Runtime.
-- Canonical copy: github.com/CowboyBingus/BingusSharedRuntime, runtime/bingus_memory.lua.
--
-- Loading: the chunk returns {VERSION = 1, new = function(runtime)} and
-- installs nothing. A mod vendors a byte-identical copy next to
-- bingus_runtime.lua and runs each file once when it loads:
--   local runtime = <bingus_runtime.lua>
--   local memory = <bingus_memory.lua>.new(runtime)   -- the api below
--   <bingus_write.lua>.extend(memory)                 -- optional: checked writes
-- This file only reads memory, page information and module files; it never
-- changes memory or page protection. A mod whose build refuses sources that can
-- modify memory vendors bingus_runtime.lua and this file only.
--
-- Windows functions are declared under private, versioned FFI names
-- (bingus_memory1_*, each with an __asm__ label naming the real export), at
-- most once per version in the whole game. ffi.cdef keeps the first prototype
-- of a name for the whole game, so a plain name would bind to whatever another
-- mod declared first. Copies of other versions declare their own names.
--
-- memory.new(runtime) -> api. runtime is the table bingus_runtime.lua returns:
-- its shared table keeps module hashes for the session. Each api has its own
-- buffers and counters; every api of one copy shares the bound functions.
--   api.read(address, size)        the bytes as a string, or nil when they cannot
--                                  all be read; allocates only that string
--   api.read_into(address, size, buffer)  into a buffer the caller keeps: true or
--                                  false, no allocation
--   api.pointer(bytes [, offset])  the user-mode pointer stored little-endian at
--                                  bytes[offset+1 .. offset+8], as uint8_t *, or nil
--   api.address(pointer)           a pointer, number or integer cdata as a Lua number
--   api.distance(a, b)             api.address(a) - api.address(b)
--   api.writable_data(address, size)  true when [address, address + size) is
--                                  committed private read-write memory: never code,
--                                  read-only, guard or module image pages
--   api.queries                    page queries made so far (one per memory region)
--   api.time()                     seconds from the performance counter (a Lua number)
--   api.module([name])             a loaded module's base as uint8_t *, or nil;
--                                  no name: the executable
--   api.module_hash(module)        SHA-256 (uppercase hex) of the module's file, read
--                                  once per session for every mod (BingusRuntime.hashes)
--   api.verify_build(build)        build = {exe_sha256, game_sha256}: true, or false and why
--   api.windows                    {ffi, kernel32, bcrypt}: the bound functions under
--                                  their Windows names, for calls the api does not cover
-- Addresses are pointer cdata (read, read_into) or pointers, numbers and integer
-- cdata (address, distance, writable_data).
--
-- Cost per call: read and read_into one ReadProcessMemory (about 1-2 us in game);
-- writable_data one VirtualQuery per memory region in the range (about 0.29 ms
-- each in game), so check only on frames that act; time() one
-- QueryPerformanceCounter (unmeasured in game). read_into, address, distance,
-- writable_data and time allocate nothing, interpreted or compiled.
local memory = {VERSION = 1}

local type, error, pcall, tonumber, ipairs, pairs = type, error, pcall, tonumber, ipairs, pairs
local max, format, concat = math.max, string.format, table.concat

local HIGH = 4294967296
local MEM_COMMIT, MEM_PRIVATE, PAGE_READWRITE = 0x1000, 0x20000, 4

-- Windows functions ----------------------------------------------------------------

-- The region record is MEMORY_BASIC_INFORMATION with each 64-bit field read as
-- two 32-bit halves, and the cell turns a pointer into two halves through one
-- union (one base, so compiled code sees the store): neither allocates when read.
-- The region record is also this file's sentinel: once it exists, every
-- declaration below exists too.
local PREFIX = 'bingus_memory1_'
local SENTINEL = 'bingus_memory1_region'
local DECLARATIONS = [[
    typedef struct bingus_memory1_region {
        uint32_t base_low, base_high, allocation_base_low, allocation_base_high;
        uint32_t allocation_protection; uint16_t partition, reserved;
        uint32_t size_low, size_high, state, protection, type, padding;
    } bingus_memory1_region;
    typedef union bingus_memory1_cell {
        const void *pointer;
        struct { uint32_t low, high; };
    } bingus_memory1_cell;
    void *bingus_memory1_GetModuleHandleA(const char *name) __asm__("GetModuleHandleA");
    uint32_t bingus_memory1_GetModuleFileNameW(void *module, uint16_t *path, uint32_t capacity) __asm__("GetModuleFileNameW");
    void *bingus_memory1_GetCurrentProcess(void) __asm__("GetCurrentProcess");
    int bingus_memory1_ReadProcessMemory(void *process, const void *address, void *buffer, size_t size,
                                         size_t *done) __asm__("ReadProcessMemory");
    uint32_t bingus_memory1_VirtualQuery(uint64_t address, bingus_memory1_region *region, size_t size) __asm__("VirtualQuery");
    int bingus_memory1_QueryPerformanceCounter(uint32_t *count) __asm__("QueryPerformanceCounter");
    int bingus_memory1_QueryPerformanceFrequency(uint32_t *frequency) __asm__("QueryPerformanceFrequency");
    void *bingus_memory1_CreateFileW(const uint16_t *path, uint32_t access, uint32_t share, void *security,
                                     uint32_t disposition, uint32_t flags, void *template_file) __asm__("CreateFileW");
    int bingus_memory1_ReadFile(void *file, void *buffer, uint32_t size, uint32_t *done, void *overlapped) __asm__("ReadFile");
    int bingus_memory1_CloseHandle(void *handle) __asm__("CloseHandle");
    int32_t bingus_memory1_BCryptOpenAlgorithmProvider(void **algorithm, const uint16_t *name, const uint16_t *provider,
                                                       uint32_t flags) __asm__("BCryptOpenAlgorithmProvider");
    int32_t bingus_memory1_BCryptCloseAlgorithmProvider(void *algorithm, uint32_t flags) __asm__("BCryptCloseAlgorithmProvider");
    int32_t bingus_memory1_BCryptCreateHash(void *algorithm, void **hash, void *object, uint32_t object_size,
                                            const void *secret, uint32_t secret_size, uint32_t flags) __asm__("BCryptCreateHash");
    int32_t bingus_memory1_BCryptHashData(void *hash, const void *data, uint32_t size, uint32_t flags) __asm__("BCryptHashData");
    int32_t bingus_memory1_BCryptFinishHash(void *hash, void *digest, uint32_t size, uint32_t flags) __asm__("BCryptFinishHash");
    int32_t bingus_memory1_BCryptDestroyHash(void *hash) __asm__("BCryptDestroyHash");
]]
local FUNCTIONS = {
    kernel32 = {'GetModuleHandleA', 'GetModuleFileNameW', 'GetCurrentProcess', 'ReadProcessMemory', 'VirtualQuery',
                'QueryPerformanceCounter', 'QueryPerformanceFrequency', 'CreateFileW', 'ReadFile', 'CloseHandle'},
    bcrypt = {'BCryptOpenAlgorithmProvider', 'BCryptCloseAlgorithmProvider', 'BCryptCreateHash',
              'BCryptHashData', 'BCryptFinishHash', 'BCryptDestroyHash'},
}

local bound, ticks_per_second
-- {ffi, kernel32, bcrypt}, each library table holding the functions above under
-- their Windows names. Declared at most once per version in the whole game.
local function bind()
    if bound then return bound end
    local ffi = require('ffi')
    if not ffi.abi('64bit') then error('Windows x64 is required', 0) end
    if not pcall(ffi.typeof, SENTINEL) then ffi.cdef(DECLARATIONS) end
    local result = {ffi = ffi}
    for library, names in pairs(FUNCTIONS) do
        local loaded, functions = ffi.load(library), {}
        for _, name in ipairs(names) do functions[name] = loaded[PREFIX .. name] end
        result[library] = functions
    end
    local frequency = ffi.new('uint32_t[2]')
    if result.kernel32.QueryPerformanceFrequency(frequency) == 0 then error('performance counter unavailable', 0) end
    ticks_per_second = frequency[0] + frequency[1] * HIGH
    bound = result
    return bound
end

-- Module files ---------------------------------------------------------------------

-- SHA-256 (uppercase hex) of the file at path (a UTF-16 string buffer).
local function sha256(windows, path)
    local ffi, kernel, bcrypt = windows.ffi, windows.kernel32, windows.bcrypt
    local file = kernel.CreateFileW(path, 0x80000000, 7, nil, 3, 0x08000000, nil)
    if file == ffi.cast('void *', -1) then error('cannot read the module file', 0) end
    local algorithm, hash = ffi.new('void *[1]'), ffi.new('void *[1]')
    local ok, result = pcall(function()
        local id = ffi.new('uint16_t[7]', {83, 72, 65, 50, 53, 54, 0})  -- "SHA256"
        if bcrypt.BCryptOpenAlgorithmProvider(algorithm, id, nil, 0) ~= 0 then error('SHA-256 unavailable', 0) end
        if bcrypt.BCryptCreateHash(algorithm[0], hash, nil, 0, nil, 0, 0) ~= 0 then
            error('SHA-256 unavailable', 0)
        end
        local buffer, count = ffi.new('uint8_t[1048576]'), ffi.new('uint32_t[1]')
        while true do
            if kernel.ReadFile(file, buffer, 1048576, count, nil) == 0 then error('module file read failed', 0) end
            if count[0] == 0 then break end
            if bcrypt.BCryptHashData(hash[0], buffer, count[0], 0) ~= 0 then error('SHA-256 failed', 0) end
        end
        local digest, hex = ffi.new('uint8_t[32]'), {}
        if bcrypt.BCryptFinishHash(hash[0], digest, 32, 0) ~= 0 then error('SHA-256 failed', 0) end
        for i = 0, 31 do hex[i + 1] = format('%02X', digest[i]) end
        return concat(hex)
    end)
    if hash[0] ~= nil then bcrypt.BCryptDestroyHash(hash[0]) end
    if algorithm[0] ~= nil then bcrypt.BCryptCloseAlgorithmProvider(algorithm[0], 0) end
    kernel.CloseHandle(file)
    if not ok then error(result, 0) end
    return result
end

-- The SHA-256 of a loaded module's file, read once per session for every mod:
-- kept in the shared table by file path.
local function module_hash(runtime, windows, module)
    local ffi = windows.ffi
    local path = ffi.new('uint16_t[32768]')
    local length = windows.kernel32.GetModuleFileNameW(module, path, 32768)
    if length == 0 or length >= 32768 then error('module file name unavailable', 0) end
    local shared = runtime.shared()
    local key = 'sha256:' .. ffi.string(path, length * 2)
    local cached = shared.hashes[key]
    if cached then return cached end
    local hex = sha256(windows, path)
    shared.hash_reads = shared.hash_reads + 1
    shared.hashes[key] = hex
    return hex
end

-- The api --------------------------------------------------------------------------

function memory.new(runtime)
    if type(runtime) ~= 'table' or type(runtime.shared) ~= 'function' then
        error('bingus_memory.lua: new(runtime) needs the table bingus_runtime.lua returns', 2)
    end
    runtime.shared()
    local windows = bind()
    local ffi, kernel = windows.ffi, windows.kernel32
    local read_memory, query, query_counter = kernel.ReadProcessMemory, kernel.VirtualQuery,
        kernel.QueryPerformanceCounter
    local process = kernel.GetCurrentProcess()
    -- ReadProcessMemory reports its count as a 64-bit size: it is read back as two
    -- 32-bit words, because reading the 64-bit value boxes a new cdata in
    -- interpreted code. Only the call writes this buffer.
    local done = ffi.new('size_t[1]')
    local done32 = ffi.cast('uint32_t *', done)
    local region, region_size = ffi.new(SENTINEL), ffi.sizeof(SENTINEL)
    local cell, counter = ffi.new('bingus_memory1_cell'), ffi.new('uint32_t[2]')
    local scratch_size = 256
    local scratch = ffi.new('uint8_t[?]', scratch_size)
    local ticks = ticks_per_second
    local api = {queries = 0, windows = windows}

    -- A pointer, number or integer cdata as a number, without allocating: a
    -- pointer passes through the cell. Exact below 2^53 (user-mode addresses
    -- end at 2^47).
    local function address_of(address)
        if type(address) == 'number' then return address end
        if type(address) == 'cdata' then
            local integer = tonumber(address)
            if integer then return integer end
        end
        cell.pointer = address
        return cell.low + cell.high * HIGH
    end

    function api.module(name)
        local handle = kernel.GetModuleHandleA(name)
        if handle == nil then return nil end
        return ffi.cast('uint8_t *', handle)
    end

    -- The bytes at address as a string, or nil when they cannot all be read.
    -- Allocates only the returned string.
    function api.read(address, size)
        if size > scratch_size then
            scratch_size = max(size, scratch_size * 2)
            scratch = ffi.new('uint8_t[?]', scratch_size)
        end
        if read_memory(process, address, scratch, size, done) == 0 or done32[0] ~= size then
            return nil
        end
        return ffi.string(scratch, size)
    end

    -- Into a buffer the caller keeps: no allocation at all.
    function api.read_into(address, size, buffer)
        return read_memory(process, address, buffer, size, done) ~= 0 and done32[0] == size
    end

    -- The user-mode pointer stored little-endian at bytes[offset+1 .. offset+8].
    function api.pointer(bytes, offset)
        offset = offset or 0
        if type(bytes) ~= 'string' or offset < 0 or offset + 8 > #bytes then return nil end
        local b1, b2, b3, b4, b5, b6, b7, b8 = bytes:byte(offset + 1, offset + 8)
        if b7 ~= 0 or b8 ~= 0 then return nil end
        local value = b1 + b2 * 256 + b3 * 65536 + b4 * 16777216 + (b5 + b6 * 256) * HIGH
        if value < 0x10000 or value >= 0x800000000000 then return nil end
        return ffi.cast('uint8_t *', value)
    end

    api.address = address_of

    function api.distance(first, second)
        return address_of(first) - address_of(second)
    end

    -- True when [address, address + size) is committed private read-write memory:
    -- never code, read-only, guard or module image pages. One VirtualQuery per
    -- region, each answered in the region record (no allocation).
    function api.writable_data(address, size)
        if type(size) ~= 'number' or size <= 0 then return false end
        local cursor = address_of(address)
        local finish = cursor + size
        while cursor < finish do
            api.queries = api.queries + 1
            if query(cursor, region, region_size) ~= region_size then return false end
            if region.state ~= MEM_COMMIT or region.type ~= MEM_PRIVATE or region.protection ~= PAGE_READWRITE then
                return false
            end
            local region_end = region.base_low + region.base_high * HIGH + region.size_low + region.size_high * HIGH
            if region_end <= cursor then return false end
            cursor = region_end
        end
        return true
    end

    -- Seconds since an arbitrary start (boot), from the performance counter read
    -- as two 32-bit halves into a reused buffer; the frequency is read once.
    function api.time()
        query_counter(counter)
        return (counter[0] + counter[1] * HIGH) / ticks
    end

    function api.module_hash(module)
        return module_hash(runtime, windows, module)
    end

    -- build: {exe_sha256, game_sha256}. true, or false and why.
    function api.verify_build(build)
        local exe, game = api.module(nil), api.module('game.dll')
        if not exe or not game then return false, 'game modules unavailable' end
        if api.module_hash(exe) ~= build.exe_sha256 or api.module_hash(game) ~= build.game_sha256 then
            return false, 'unsupported game build'
        end
        return true
    end

    return api
end

return memory
end
mbm_files.bingus_runtime = function(...)
-- bingus_runtime.lua, version 1: the core of Bingus Shared Runtime.
-- Canonical copy: github.com/CowboyBingus/BingusSharedRuntime, runtime/bingus_runtime.lua.
--
-- Helldivers 2 runs the game and every Lua mod in one LuaJIT state, with one
-- global update chain. This file gives a mod the update guard every mod used
-- to write by hand, and the session table all runtime copies share. It uses no
-- FFI and no system function.
--
-- Loading: each runtime file is one chunk that returns a table and installs
-- nothing until the mod asks. A mod vendors byte-identical copies of the files
-- it needs and runs each once when it loads:
--   local runtime = <bingus_runtime.lua>              -- this file: shared(), guard()
--   local memory = <bingus_memory.lua>.new(runtime)   -- reads, page checks, module hashes, time()
--   <bingus_write.lua>.extend(memory)                 -- checked writes, added to memory
-- A mod that never touches memory vendors this file alone; one that only reads
-- vendors this file and bingus_memory.lua.
--
-- Copies of different versions can run in the same game. Their session state
-- lives in one global table, BingusRuntime = {hashes, statuses, versions,
-- hash_reads}, which every copy of every version shares.
--
-- runtime.shared([globals]) -> BingusRuntime, created or repaired.
-- runtime.guard(options) -> guard: the update and shutdown wrappers. The
-- previous update runs outside pcall, so its errors reach the game unchanged
-- (P1); the first failure survives shutdown as "stopped after: <reason>" (P2);
-- 8 errors stop the mod, counted per burst so rare transient errors never add
-- up (P3); a mod that can restore its state pauses after an error below it and
-- resumes when the updates below run cleanly again; every argument and return
-- value passes through; a status table per mod lands in BingusRuntime.statuses.
--
-- Per-frame cost of a guard: the mod's step under pcall, a few boolean tests
-- and stores and two integer counters around the previous update; no
-- allocation, closure or system call. Unmeasured in game.
local runtime = {VERSION = 1}

local type, pcall, error, tostring, rawget, rawset, ipairs = type, pcall, error, tostring, rawget, rawset, ipairs

-- Session state shared by every copy of every version ----------------------------

local SHARED = 'BingusRuntime'
local SHARED_TABLES = {'hashes', 'statuses', 'versions'}

-- Another copy, another version or another mod may have left the table
-- incomplete (even `BingusRuntime = {}`): missing or broken fields are filled in,
-- so one stray assignment cannot stop every mod on the runtime.
function runtime.shared(globals)
    globals = globals or _G
    local shared = rawget(globals, SHARED)
    if type(shared) ~= 'table' then
        shared = {}
        rawset(globals, SHARED, shared)
    end
    for _, field in ipairs(SHARED_TABLES) do
        if type(rawget(shared, field)) ~= 'table' then rawset(shared, field, {}) end
    end
    if type(rawget(shared, 'hash_reads')) ~= 'number' then rawset(shared, 'hash_reads', 0) end
    rawset(rawget(shared, 'versions'), runtime.VERSION, true)
    return shared
end

-- Update guard -----------------------------------------------------------------------

-- options:
--   name    key in BingusRuntime.statuses (required, one guard per name)
--   step    function(dt, ...) before the previous update, every frame while running
--   after   function() after the previous update returned, while running
--   stop    function(reason) once, when the guard stops or the game shuts down;
--           its errors are kept in status.stop_error, never raised
--   pause   function(reason), optional: an update below this mod raised; restore
--           the game state and reset the mod to a fresh start. With it the guard
--           pauses (no step, no after) and resumes once the updates below have
--           returned on `resume` frames in a row (default 60). Without it such an
--           error stops the guard. A pause that raises stops the guard.
--   log     function(line) for the guard's few lines (errors, pauses, resumes, stop)
--   errors  errors that stop the guard (default 8), counted separately for the
--           mod's own step and after and for the updates below it. A count starts
--           again after `clean` frames without such an error (default 3600, about a
--           minute at 60 FPS), so rare transient errors never add up to a stop.
--   env     the table holding update and shutdown (default _G)
-- guard.install() wraps env.update and env.shutdown and returns the guard.
-- guard.stop(reason) stops it from the mod (a refusal counts as the first failure).
-- guard.running() is true from install until a stop or shutdown.
-- guard.status: {name, version, state, installed, errors, lower_errors, pauses,
--   first_error, burst_error, first_failure, stop_error}; state is 'new', 'running',
--   'paused: <reason>', 'stopped: <reason>', then at shutdown 'stopped' or
--   'stopped after: <first failure>'.
function runtime.guard(options)
    local name = options.name
    if type(name) ~= 'string' or name == '' then error('guard name required', 0) end
    local shared = runtime.shared(options.env)
    if shared.statuses[name] and shared.statuses[name].installed then error('guard ' .. name .. ' already installed', 0) end
    local status = {name = name, version = runtime.VERSION, state = 'new', installed = false, errors = 0,
        lower_errors = 0, pauses = 0}
    shared.statuses[name] = status
    local step, after_step, stop_work, pause_work, log = options.step, options.after, options.stop, options.pause,
        options.log
    local limit, resume_after, clean_after = options.errors or 8, options.resume or 60, options.clean or 3600
    local previous_update, previous_shutdown
    local in_previous, stopped, paused, failed = false, false, false, false
    local clean_run, lower_run = 0, 0

    local function note(line)
        if log then pcall(log, line) end
    end

    local function halt(reason)
        if stopped then return end
        stopped, paused = true, false
        status.first_failure = status.first_failure or reason
        status.state = 'stopped: ' .. reason
        note(name .. ' stopped: ' .. reason)
        if stop_work then
            local ok, why = pcall(stop_work, reason)
            if not ok then status.stop_error = tostring(why) end
        end
    end

    -- The mod's own step or after raised: one log line per burst of errors.
    local function failed_step(problem)
        failed, clean_run = true, 0
        status.errors = status.errors + 1
        local text = tostring(problem)
        status.first_error = status.first_error or text
        if status.errors == 1 then
            status.burst_error = text
            note(name .. ' error: ' .. text)
        end
        if status.errors >= limit then halt('stopped after ' .. limit .. ' errors: ' .. status.burst_error) end
    end

    -- An update below this mod raised (seen on the next frame).
    local function failed_below()
        lower_run = 0
        status.lower_errors = status.lower_errors + 1
        if not pause_work then return halt('the previous update failed') end
        if status.lower_errors >= limit then
            return halt('stopped after ' .. limit .. ' failed updates below this mod')
        end
        if paused then return end
        paused = true
        status.pauses = status.pauses + 1
        status.state = 'paused: the previous update failed'
        note(name .. ' paused: the previous update failed')
        local ok, why = pcall(pause_work, 'the previous update failed')
        if not ok then halt('pause failed: ' .. tostring(why)) end
    end

    local function resume_when_clean()
        if paused and lower_run >= resume_after then
            paused = false
            status.state = 'running'
            note(name .. ' resumed after ' .. resume_after .. ' clean frames')
        end
    end

    -- Counts a frame without an own error, which also clears an old burst.
    local function count_clean()
        if failed then return end
        clean_run = clean_run + 1
        if clean_run == clean_after then status.errors = 0 end
    end

    local function finish(...)
        in_previous = false
        lower_run = lower_run + 1
        if lower_run == clean_after then status.lower_errors = 0 end
        if not stopped and not paused then
            if after_step then
                local ok, problem = pcall(after_step)
                if not ok then failed_step(problem) end
            end
            count_clean()
        end
        return ...
    end

    -- The previous update runs outside pcall: its errors (value and traceback)
    -- reach the game unchanged. One that raised leaves in_previous set, and the
    -- next frame pauses (or stops) this mod and keeps forwarding.
    local function update(...)
        failed = false
        if in_previous then
            in_previous = false
            if not stopped then failed_below() end
        end
        resume_when_clean()
        if step and not stopped and not paused then
            local ok, problem = pcall(step, ...)
            if not ok then failed_step(problem) end
        end
        in_previous = true
        return finish(previous_update(...))
    end

    local function shutdown(...)
        if in_previous then
            in_previous = false
            status.first_failure = status.first_failure or 'the previous update failed'
        end
        local failure = status.first_failure
        if not stopped then
            stopped = true
            if stop_work then
                local ok, why = pcall(stop_work, 'shutdown')
                if not ok then status.stop_error = tostring(why) end
            end
        end
        status.state = failure and ('stopped after: ' .. failure) or 'stopped'
        if previous_shutdown then return previous_shutdown(...) end
    end

    local guard = {status = status}

    function guard.install()
        local env = options.env or _G
        if status.installed then error('guard ' .. name .. ' already installed', 0) end
        previous_update = rawget(env, 'update')
        if type(previous_update) ~= 'function' then error('game update unavailable', 0) end
        previous_shutdown = rawget(env, 'shutdown')
        rawset(env, 'update', update)
        rawset(env, 'shutdown', shutdown)
        status.installed, status.state = true, 'running'
        return guard
    end

    function guard.stop(reason)
        halt(tostring(reason))
    end

    function guard.running()
        return status.installed and not stopped
    end

    return guard
end

return runtime
end
mbm_files.capture = function(...)
-- Mod Bindings Menu's key capture for extended bindings on the MODS tab:
-- choosing a binding's key the way a native row's capture widget does.
-- src/mod_bindings_menu.lua runs this file once as mbm_files.capture(mbm); it
-- adds begin_capture, update_capture, cancel_capture and capture_phase to mbm.
--
-- A capture belongs to a page: the keyboard page captures keyboard keys and
-- mouse buttons, the controller page controller buttons. It replaces the
-- binding's alternatives of that page's devices and keeps the others, so a
-- binding can have a keyboard key and a controller button.
--
-- Phases: idle -> arming -> capturing -> releasing -> idle.
-- - arming: the row was activated; wait until the click, key or button that
--   activated it is released, so that input is never captured.
-- - capturing: the first newly pressed input decides:
--     Back (Escape; B on a controller, from either page) cancels;
--     Delete or Backspace (X on the controller page) clears the page's keys;
--     a modifier (Ctrl, Shift, Alt; a shoulder button or trigger on the
--       controller page) waits: another input pressed while it is held makes a
--       chord with it, releasing it alone binds the modifier;
--     anything else becomes the binding, with the modifiers held at that moment.
--   Back and clear are reserved: they cannot be bound by capture (authors can
--   give them in a default or with set_binding). The keyboard's own entries
--   for mouse buttons (names ending in **) and mouse double clicks are ignored.
-- - releasing: wait until every input of the capture is released, so the new
--   binding does not fire from the press that chose it.
-- From arming to the end every mod binding reads false (state.suppressed), and
-- the page's Back guard is held (hooks.hold_back), so Back cancels the capture
-- instead of closing the page. Focus loss (after the window was seen focused:
-- an engine that never reports focus cannot cancel every capture), a page or
-- world change, an error, or TIMEOUT seconds without a choice cancel. Every
-- exit restores the guard (hooks.release_back) and starts a new input epoch,
-- so a key held through the capture fires no press afterwards.
-- Cost: nothing while idle; while capturing, on the page only, one any_pressed
-- per device (per connected pad), the window focus and one read per held
-- modifier per frame.
local mbm = ...
local state, note = mbm.state, mbm.note
local engine_source, store_alternatives = mbm.engine_source, mbm.store_alternatives
local engine_down, engine_any_pressed, window_focused = mbm.engine_down, mbm.engine_any_pressed, mbm.window_focused
local current_alternatives, binding_info = mbm.current_alternatives, mbm.binding_info

local IDLE, ARMING, CAPTURING, RELEASING = 'idle', 'arming', 'capturing', 'releasing'
local TIMEOUT = 10
local PAGES = {keyboard = {k = true, m = true}, controller = {p = true}}
local DEVICES = {'k', 'm', 'p'}
-- Engine button names (looked up when a capture first begins; a name the
-- engine does not know is left out). Controllers use the engine's Xbox names.
local ACTIVATORS = {k = {'enter', 'numpad enter', 'space'}, m = {'left'}, p = {'a'}}
local BACK = {k = {'esc', 'escape'}, p = {'b'}}
local CLEAR = {k = {'delete', 'backspace'}, p = {'x'}}
local MODIFIERS = {k = {'left ctrl', 'right ctrl', 'left shift', 'right shift', 'left alt', 'right alt'},
                   p = {'left_shoulder', 'right_shoulder', 'left_trigger', 'right_trigger'}}
-- The device whose modifiers go with a main input.
local MODIFIER_OF = {k = 'k', m = 'k', p = 'p'}

local capture = {phase = IDLE, id = nil, page = nil, hooks = nil, timer = 0, held = {}, pending = nil,
                 trigger = 'press', focused_seen = false, names = nil}

-- name -> index sets per device, looked up once per session through the engine.
local function lookup(engine)
    if capture.names then return capture.names end
    local names = {activators = {}, back = {}, clear = {}, modifiers = {}}
    local function fill(target, lists)
        for device, list in pairs(lists) do
            local tbl = engine.devices[device]
            target[device] = {}
            for _, name in ipairs(list) do
                local ok, index = false, nil
                if tbl then ok, index = pcall(tbl.button_id, name) end
                if ok and type(index) == 'number' then target[device][index] = true end
            end
        end
    end
    fill(names.activators, ACTIVATORS)
    fill(names.back, BACK)
    fill(names.clear, CLEAR)
    fill(names.modifiers, MODIFIERS)
    capture.names = names
    return names
end

local function any_down(set_by_device)
    for device, set in pairs(set_by_device) do
        for index in pairs(set) do
            if engine_down(device, index) then return true end
        end
    end
    return false
end

local function member(set_by_device, device, index)
    return set_by_device[device] ~= nil and set_by_device[device][index] == true
end

-- Ends the capture whatever its phase: the guard goes back, mod bindings read
-- again from a new input epoch.
local function finish(reason)
    local hooks = capture.hooks
    capture.phase, capture.id, capture.page, capture.hooks, capture.pending = IDLE, nil, nil, nil, nil
    capture.focused_seen = false
    for key in pairs(capture.held) do capture.held[key] = nil end
    state.suppressed = false
    state.input_epoch = state.input_epoch + 1
    if hooks and hooks.release_back then
        local ok, problem = pcall(hooks.release_back)
        if not ok then note('Restoring the page\'s Back guard failed: ' .. tostring(problem)) end
    end
    if reason then note('Key capture ended: ' .. reason .. '.') end
end

-- The trigger a captured key keeps: the first of the page's alternatives',
-- else the binding's first alternative's, else press.
local function current_trigger(alternatives, page)
    for _, alternative in ipairs(alternatives) do
        if PAGES[page][alternative.inputs[1].device] then return alternative.trigger end
    end
    return alternatives[1] and alternatives[1].trigger or 'press'
end

-- Starts a capture for extended binding id on page 'keyboard' (the default) or
-- 'controller'. hooks (optional): {hold_back = fn, release_back = fn} for the
-- page's Back guard. Returns true, or false and a reason.
local function begin_capture(id, hooks, page)
    page = page or 'keyboard'
    local record = state.registry[id]
    if capture.phase ~= IDLE then return false, 'a capture is running' end
    if not PAGES[page] then return false, 'unknown page' end
    if not record or not record.extended then return false, 'not an extended binding' end
    if binding_info(id).state == 'inactive' then return false, 'the binding was saved by a newer version' end
    local engine = engine_source()
    local alternatives = engine and current_alternatives(id)
    if not alternatives then return false, 'input not ready' end
    lookup(engine)
    capture.phase, capture.id, capture.page, capture.hooks, capture.timer = ARMING, id, page, hooks, 0
    capture.trigger, capture.focused_seen = current_trigger(alternatives, page), false
    state.suppressed = true
    if hooks and hooks.hold_back then
        local ok, problem = pcall(hooks.hold_back)
        if not ok then
            finish('the page\'s Back guard could not be held (' .. tostring(problem) .. ')')
            return false, 'back guard unavailable'
        end
    end
    return true
end

-- Records the choice: inputs (main first) replace the page's alternatives, {}
-- removes them; the other page's alternatives stay. Then waits for release.
local function choose(inputs)
    local devices, kept, at = PAGES[capture.page], {}, nil
    for _, alternative in ipairs(current_alternatives(capture.id) or {}) do
        if devices[alternative.inputs[1].device] then
            at = at or #kept + 1
        elseif #kept < mbm.MAX_ALTERNATIVES - 1 then
            kept[#kept + 1] = alternative
        end
    end
    if #inputs > 0 then table.insert(kept, at or #kept + 1, {inputs = inputs, trigger = capture.trigger}) end
    store_alternatives(capture.id, kept)
    for _, input in ipairs(inputs) do capture.held[input.device .. ':' .. input.index] = input end
    capture.phase = RELEASING
end

local function held_modifiers(names, device)
    local inputs = {}
    for index in pairs(names.modifiers[device] or {}) do
        if engine_down(device, index) then inputs[#inputs + 1] = {device = device, index = index} end
    end
    table.sort(inputs, function(a, b) return a.index < b.index end)
    return inputs
end

-- The keyboard's entries for mouse buttons (the mouse reports those) and mouse
-- double clicks are not inputs to capture.
local function ignored(engine, device, index)
    local tbl = engine.devices[device]
    if device == 'p' or not tbl or type(tbl.button_name) ~= 'function' then return false end
    local ok, name = pcall(tbl.button_name, index)
    if not ok or type(name) ~= 'string' then return false end
    return device == 'k' and name:find('%*%*$') ~= nil or device == 'm' and name:find('double', 1, true) ~= nil
end

-- One newly pressed input on a device of the capture's page, decided as
-- described at the top.
local function decide(engine, names, device, index)
    if ignored(engine, device, index) then return end
    if member(names.clear, device, index) then
        choose({})
        capture.held[device .. ':' .. index] = {device = device, index = index}
        return
    end
    if member(names.modifiers, device, index) then
        capture.pending = capture.pending or {device = device, index = index}
        return
    end
    local inputs = {{device = device, index = index}}
    for _, modifier in ipairs(held_modifiers(names, MODIFIER_OF[device])) do
        if #inputs < mbm.MAX_INPUTS then inputs[#inputs + 1] = modifier end
    end
    choose(inputs)
end

-- The input first pressed this frame on device, if any: Back cancels from
-- either page; on the page's devices it is decided. Returns whether the
-- capture left the capturing phase.
local function pressed_on(engine, names, device)
    local index = engine_any_pressed(device)
    if not index then return false end
    if member(names.back, device, index) then
        finish('cancelled')
        return true
    end
    if PAGES[capture.page][device] then decide(engine, names, device, index) end
    return capture.phase ~= CAPTURING
end

local function capturing(engine, names)
    for _, device in ipairs(DEVICES) do
        if pressed_on(engine, names, device) then return end
    end
    -- A modifier pressed alone and released alone becomes the binding.
    local pending = capture.pending
    if pending and not engine_down(pending.device, pending.index) then
        capture.pending = nil
        choose({pending})
        for key in pairs(capture.held) do capture.held[key] = nil end
    end
end

-- Whether the capture may go on as far as focus goes: focused (true, false,
-- or nil to ask the engine) is only lost after the window was seen focused.
local function focus_kept(focused)
    if focused == nil then focused = window_focused() end
    if focused == true then capture.focused_seen = true end
    return focused ~= false or not capture.focused_seen
end

-- Releasing: ends the capture once every input it chose is released.
local function releasing()
    for _, input in pairs(capture.held) do
        if engine_down(input.device, input.index) then return end
    end
    finish(nil)
end

-- One frame of the capture, from the page's frame. focused: whether the game
-- window has focus; nil asks the engine (stingray.Window.has_focus).
local function update_capture(seconds, focused)
    if capture.phase == IDLE then return end
    local engine = engine_source()
    if not engine then
        finish('input unavailable')
        return
    end
    if not focus_kept(focused) then
        finish('the game lost focus')
        return
    end
    capture.timer = capture.timer + (seconds or 0)
    if capture.phase == ARMING then
        if not any_down(capture.names.activators) then capture.phase = CAPTURING end
    elseif capture.phase == CAPTURING then
        if capture.timer > TIMEOUT then
            finish('no key chosen in ' .. TIMEOUT .. ' seconds')
            return
        end
        capturing(engine, capture.names)
    end
    if capture.phase == RELEASING then releasing() end
end

local function cancel_capture(reason)
    if capture.phase ~= IDLE then finish(reason or 'cancelled') end
end

mbm.begin_capture, mbm.update_capture, mbm.cancel_capture = begin_capture, update_capture, cancel_capture
function mbm.capture_phase() return capture.phase, capture.id, capture.page end

if type(jit) == 'table' and type(jit.off) == 'function' then
    for _, fn in ipairs({lookup, any_down, member, finish, current_trigger, begin_capture, choose, held_modifiers,
                         ignored, decide, pressed_on, capturing, focus_kept, releasing, update_capture,
                         cancel_capture, mbm.capture_phase}) do
        jit.off(fn)
    end
end
end
mbm_files.extended = function(...)
-- Mod Bindings Menu's extended bindings: bindings without a native action. A
-- registration gets one when the 36 native actions are all held (or with
-- options.backend = 'extended'), so the number of bindings has no fixed limit.
-- src/mod_bindings_menu.lua runs this file once as mbm_files.extended(mbm); it
-- adds register_extended, extended_known, extended_down, set_binding, binding,
-- binding_info, EXTENDED_DEVICES and EXTENDED_TRIGGERS to mbm.
--
-- Native bindings are unchanged: the game evaluates them on every device with
-- its own activation types. Extended bindings read the engine's input instead
-- (stingray.Keyboard, Mouse and Pad1 to Pad4, never Windows polling) and
-- support what this file evaluates, listed in EXTENDED_DEVICES and
-- EXTENDED_TRIGGERS:
-- - press: true on the frame its inputs become held, release: on the frame they
--   stop being held, hold: while they are held;
-- - alternatives: any one of a binding's alternatives satisfies it;
-- - modifiers: an alternative's later inputs must be held with its first one.
--   Holding more keys than an alternative names does not stop it;
-- - controller buttons (Xbox names: a, b, x, y, left_shoulder...) count on any
--   connected pad, checked each frame one is read, so a pad plugged in or
--   removed during play is followed.
-- A binding never changes backend: src/extended_store.lua keeps a line for
-- every extended id.
--
-- Cost. Nothing per frame by itself: a binding is evaluated when a mod asks for
-- it (is_down, poll), at most once per frame, and each physical input is read
-- from the engine at most once per frame however many bindings use it; a
-- controller input reads each connected pad, after one connected check per pad
-- per frame. One engine button read cost about 0.1 us in game (gate 1, ship,
-- 2026-10-13: 10000 Keyboard.button calls); the connected check is unmeasured in
-- game.
local mbm = ...
local state, note = mbm.state, mbm.note
local load_extended, MAX_ALTERNATIVES, MAX_INPUTS = mbm.load_extended, mbm.MAX_ALTERNATIVES, mbm.MAX_INPUTS

-- Device codes as in the bindings file, the engine's input tables, and the
-- names authors use.
local ENGINE_DEVICES = {k = 'Keyboard', m = 'Mouse'}
local ENGINE_PADS = {'Pad1', 'Pad2', 'Pad3', 'Pad4'}
local DEVICE_CODES = {keyboard = 'k', mouse = 'm', controller = 'p'}
local DEVICE_NAMES = {k = 'keyboard', m = 'mouse', p = 'controller'}
local DEVICE_KEYS = {k = 1, m = 2, p = 3}
-- Modifiers are keyboard keys for keyboard and mouse bindings, controller
-- buttons for controller bindings.
local MODIFIER_DEVICE = {k = 'k', m = 'k', p = 'p'}
local TRIGGERS = {press = true, release = true, hold = true}
-- What extended bindings support (ModBindingsMenu.extended).
local EXTENDED_DEVICES = {'keyboard', 'mouse', 'controller'}
local EXTENDED_TRIGGERS = {'press', 'release', 'hold'}
local SUPPORTED_DEVICE = {k = true, m = true, p = true}

-- The engine's input tables, found once stingray has them. devices.p is the
-- first pad, for button names and ids (every pad uses the same); pads lists
-- them all; connected holds the connected ones, checked once per frame.
local source = {ready = false, devices = {}, pads = {}, connected = {}, connected_count = 0, connected_frame = nil}
local function usable(device)
    return type(device) == 'table' and type(device.button) == 'function' and type(device.button_id) == 'function'
end
local function engine_source()
    if source.ready then return source end
    local engine = rawget(_G, 'stingray')
    if type(engine) ~= 'table' then return nil end
    for code, name in pairs(ENGINE_DEVICES) do
        if usable(engine[name]) then source.devices[code] = engine[name] end
    end
    local pads = {}
    for _, name in ipairs(ENGINE_PADS) do
        if usable(engine[name]) then pads[#pads + 1] = engine[name] end
    end
    source.pads, source.devices.p = pads, pads[1]
    source.ready = source.devices.k ~= nil
    return source.ready and source or nil
end
mbm.engine_source = engine_source

-- The pads connected this frame (a pad without a connected function counts as
-- connected): the list and its length, checked at most once per frame.
local function connected_pads()
    if source.connected_frame == state.frame then return source.connected, source.connected_count end
    local pads, connected, count = source.pads, source.connected, 0
    for n = 1, #pads do
        local pad, ok, yes = pads[n], true, true
        if type(pad.connected) == 'function' then ok, yes = pcall(pad.connected) end
        if ok and yes then
            count = count + 1
            connected[count] = pad
        end
    end
    source.connected_frame, source.connected_count = state.frame, count
    return connected, count
end

local function button_down(device, index)
    local ok, value = pcall(device.button, index)
    return ok and (value == true or type(value) == 'number' and value > 0.5)
end

-- Whether an input is held now, read from the engine: a controller button on
-- any connected pad.
local function engine_down(device_code, index)
    if device_code == 'p' then
        local pads, count = connected_pads()
        for n = 1, count do
            if button_down(pads[n], index) then return true end
        end
        return false
    end
    local device = source.devices[device_code]
    return device ~= nil and button_down(device, index)
end

-- The button first pressed this frame on a device (any connected pad for 'p'),
-- or nil.
local function device_any_pressed(device)
    if not device or type(device.any_pressed) ~= 'function' then return nil end
    local ok, index = pcall(device.any_pressed)
    if ok and type(index) == 'number' then return index end
    return nil
end
local function engine_any_pressed(device_code)
    if device_code ~= 'p' then return device_any_pressed(source.devices[device_code]) end
    local pads, count = connected_pads()
    for n = 1, count do
        local index = device_any_pressed(pads[n])
        if index then return index end
    end
    return nil
end

-- Whether the game window has focus: true, false, or nil when the engine does
-- not say.
local function window_focused()
    local engine = rawget(_G, 'stingray')
    local window = type(engine) == 'table' and engine.Window
    if type(window) ~= 'table' or type(window.has_focus) ~= 'function' then return nil end
    local ok, focused = pcall(window.has_focus)
    if ok and type(focused) == 'boolean' then return focused end
    return nil
end

-- One physical input's state, read from the engine at most once per frame:
-- sample_frame[key] is the frame it was read in, sample_down[key] its state.
local sample_frame, sample_down = {}, {}
local function input_down(input)
    local key = input.key
    if sample_frame[key] == state.frame then return sample_down[key] end
    local down = engine_down(input.device, input.index)
    sample_frame[key], sample_down[key] = state.frame, down
    return down
end

-- An author's binding spec: nil (none), a button name, or a list of
-- alternatives, each a button name or {button = name, device = 'keyboard' |
-- 'mouse' | 'controller', modifiers = {names}, trigger = 'press' | 'release' |
-- 'hold'}. {} means no keys. Returns {{device, names = {main, modifiers...},
-- trigger}...}, or nil when spec is not one.
-- {button, modifiers...}, or nil when modifiers is not a list of names that fits.
local function spec_names(button, modifiers)
    local names = {button}
    if modifiers == nil then return names end
    if type(modifiers) ~= 'table' then return nil end
    for m = 1, #modifiers do
        if type(modifiers[m]) ~= 'string' or modifiers[m] == '' or #names >= MAX_INPUTS then return nil end
        names[#names + 1] = modifiers[m]
    end
    return names
end

-- One alternative of a spec as {device, names, trigger}, or nil.
local function spec_alternative(alternative)
    if type(alternative) == 'string' then alternative = {button = alternative} end
    if type(alternative) ~= 'table' or type(alternative.button) ~= 'string' or alternative.button == '' then
        return nil
    end
    local device = DEVICE_CODES[alternative.device or 'keyboard']
    local trigger = alternative.trigger or 'press'
    if not device or not SUPPORTED_DEVICE[device] or not TRIGGERS[trigger] then return nil end
    local names = spec_names(alternative.button, alternative.modifiers)
    return names and {device = device, names = names, trigger = trigger}
end

local function parse_spec(spec)
    if type(spec) == 'string' then spec = {spec} end
    if type(spec) ~= 'table' or #spec > MAX_ALTERNATIVES then return nil end
    local alternatives = {}
    for index = 1, #spec do
        alternatives[index] = spec_alternative(spec[index])
        if not alternatives[index] then return nil end
    end
    return alternatives
end
mbm.parse_spec = parse_spec

-- An input the evaluator reads: {device, index, key}.
local function make_input(device, index)
    return {device = device, index = index, key = DEVICE_KEYS[device] * 65536 + index}
end

-- A parsed spec's alternatives as file alternatives ({inputs = {{device, index}},
-- trigger}), the names looked up through the engine; nil and the first name
-- the engine does not know (or 'input not ready').
local function resolve_spec(alternatives)
    local engine = engine_source()
    if not engine then return nil, 'input not ready' end
    local resolved = {}
    for index, alternative in ipairs(alternatives) do
        local inputs = {}
        for position, name in ipairs(alternative.names) do
            local device = position == 1 and alternative.device or MODIFIER_DEVICE[alternative.device]
            local table_ = engine.devices[device]
            local ok, id = false, nil
            if table_ then ok, id = pcall(table_.button_id, name) end
            if not ok or type(id) ~= 'number' or id < 0 or id > 65535 or id % 1 ~= 0 then return nil, name end
            inputs[position] = {device = device, index = id}
        end
        resolved[index] = {inputs = inputs, trigger = alternative.trigger}
    end
    return resolved
end

-- The evaluator's copy of file alternatives: inputs with their keys, and per
-- alternative whether it was held when last evaluated.
local function runtime_alternatives(alternatives)
    local copies = {}
    for index, alternative in ipairs(alternatives) do
        local inputs = {}
        for position, input in ipairs(alternative.inputs) do inputs[position] = make_input(input.device, input.index) end
        copies[index] = {inputs = inputs, trigger = alternative.trigger, hold = alternative.trigger == 'hold',
                         press = alternative.trigger == 'press', was = false}
    end
    return copies
end

local unresolved_logged = {}
-- The author's default as the evaluator's alternatives; nil while the engine
-- has no input tables. A default naming a button the engine does not know
-- starts without keys (logged once).
local function default_alternatives(record)
    if not record.spec then return {} end
    local resolved, problem = resolve_spec(record.spec)
    if resolved then return runtime_alternatives(resolved) end
    if problem == 'input not ready' then return nil end
    if not unresolved_logged[record.id] then
        unresolved_logged[record.id] = true
        note('Default of ' .. record.id .. ' names a button the engine does not know ("' .. problem ..
             '"); the binding starts without keys.')
    end
    return {}
end

-- Sets record.alternatives from the saved binding or the author's default.
-- False while the engine has no input tables yet: saved alternatives are read
-- through them too.
local function resolve(record)
    if not engine_source() then return false end
    local store = load_extended()
    local saved = store.records[record.id]
    record.inactive = store.newer or saved ~= nil and saved.kind == 'unknown'
    local alternatives
    if record.inactive or saved and saved.kind == 'cleared' then
        alternatives = {}
    elseif saved and saved.kind == 'set' then
        alternatives = runtime_alternatives(saved.alternatives)
    else
        alternatives = default_alternatives(record)
    end
    record.alternatives = alternatives
    return alternatives ~= nil
end

-- Whether an extended binding is satisfied this frame (see the top of this
-- file), at most one evaluation per frame. state.suppressed (a key capture on
-- a binding page) makes it false, inputs still read so a key held through the
-- capture fires no press afterwards. After a change (record.epoch behind
-- state.input_epoch) the first evaluation only records which inputs are held.
-- Whether one alternative fires this frame, its held state recorded for the
-- next; after a change (resync) press and release only record it.
local function alternative_fires(alternative, resync)
    local inputs, held = alternative.inputs, true
    for i = 1, #inputs do
        if not input_down(inputs[i]) then
            held = false
            break
        end
    end
    local was = alternative.was
    alternative.was = held
    if alternative.hold then return held end
    if resync then return false end
    if alternative.press then return held and not was end
    return was and not held
end

local function extended_down(record)
    if record.frame == state.frame then return record.down end
    record.frame = state.frame
    if not record.alternatives and not resolve(record) then
        record.down = false
        return false
    end
    local resync = record.epoch ~= state.input_epoch
    record.epoch = state.input_epoch
    local alternatives, down = record.alternatives, false
    -- Every alternative is evaluated, so each records its held state.
    for a = 1, #alternatives do
        if alternative_fires(alternatives[a], resync) then down = true end
    end
    record.down = down and not state.suppressed
    return record.down
end

local function sort_extended()
    table.sort(state.extended_order, function(a, b)
        if a.category ~= b.category then return a.category < b.category end
        return a.position < b.position
    end)
end

-- Registers id as an extended binding. spec: parse_spec's result or nil.
local function register_extended(record_fields, spec, reason)
    local store = load_extended()
    local id = record_fields.id
    if not store.records[id] and not store.newer then
        store.records[id], store.dirty = {kind = 'default'}, true
    end
    local record = record_fields
    record.extended, record.spec = true, spec
    state.extended_count = state.extended_count + 1
    record.position = state.extended_count
    state.registry[id] = record
    state.extended_order[#state.extended_order + 1] = record
    sort_extended()
    note('Registered ' .. id .. ' as an extended binding (' .. reason .. ') under ' .. record.category .. '.')
    return true
end

local function extended_known(id)
    return load_extended().records[id] ~= nil
end

-- ModBindingsMenu.set_binding(id, spec): the keys of an extended binding, as a
-- player would choose them on the MODS tab. spec as parse_spec; {} removes
-- every key (the author's default no longer applies), nil restores the
-- author's default. Returns true, or false and a reason. Saved from the step.
local function set_binding(id, spec)
    local record = state.registry[id]
    if not record or not record.extended then return false, 'not an extended binding' end
    local store = load_extended()
    if store.newer then return false, 'the bindings file is from a newer version' end
    local entry
    if spec == nil then
        entry = {kind = 'default'}
    else
        local parsed = parse_spec(spec)
        if not parsed then return false, 'invalid binding' end
        local resolved, problem = resolve_spec(parsed)
        if not resolved then
            return false, problem == 'input not ready' and problem or 'unknown button: ' .. problem
        end
        entry = #resolved == 0 and {kind = 'cleared'} or {kind = 'set', alternatives = resolved}
    end
    store.records[id], store.dirty = entry, true
    state.bindings_version = state.bindings_version + 1
    record.alternatives, record.frame, record.epoch = nil, nil, nil
    return true
end

-- Stores file alternatives captured on the page: the same as set_binding with
-- inputs that are already engine indices.
local function store_alternatives(id, alternatives)
    local record = state.registry[id]
    local store = load_extended()
    if not record or not record.extended or store.newer then return false end
    store.records[id] = #alternatives == 0 and {kind = 'cleared'} or {kind = 'set', alternatives = alternatives}
    store.dirty, state.bindings_version = true, state.bindings_version + 1
    record.alternatives, record.frame, record.epoch = nil, nil, nil
    return true
end

-- An extended binding's current keys as file alternatives ({inputs = {{device,
-- index}...}, trigger}), new tables; nil before engine input exists.
local function current_alternatives(id)
    local record = state.registry[id]
    if not record or not record.extended then return nil end
    if not record.alternatives and not resolve(record) then return nil end
    local list = {}
    for index, alternative in ipairs(record.alternatives) do
        local inputs = {}
        for position, input in ipairs(alternative.inputs) do
            inputs[position] = {device = input.device, index = input.index}
        end
        list[index] = {inputs = inputs, trigger = alternative.trigger}
    end
    return list
end

local function engine_text(input, field)
    local engine = engine_source()
    local device = engine and engine.devices[input.device]
    if device and type(device[field]) == 'function' then
        local ok, name = pcall(device[field], input.index)
        if ok and type(name) == 'string' and name ~= '' then return name end
    end
    return nil
end

-- The engine's name of an input (what set_binding takes).
local function input_name(input)
    return engine_text(input, 'button_name') or DEVICE_NAMES[input.device] .. ' ' .. input.index
end

-- The name the player reads: the engine's localized name, else its name.
local function input_label(input)
    return engine_text(input, 'button_locale_name') or input_name(input)
end

-- ModBindingsMenu.binding(id): an extended binding's keys as
-- {{device, button, modifiers = {...}, trigger}...} with the engine's button
-- names ({} without keys), nil for any other id or before engine input exists.
local function binding(id)
    local record = state.registry[id]
    if not record or not record.extended then return nil end
    if not record.alternatives and not resolve(record) then return nil end
    local list = {}
    for index, alternative in ipairs(record.alternatives) do
        local modifiers = {}
        for position = 2, #alternative.inputs do modifiers[position - 1] = input_name(alternative.inputs[position]) end
        list[index] = {device = DEVICE_NAMES[alternative.inputs[1].device], button = input_name(alternative.inputs[1]),
                       modifiers = modifiers, trigger = alternative.trigger}
    end
    return list
end

-- ModBindingsMenu.binding_info(id): nil when not registered, else
-- {backend = 'native', slot} or {backend = 'extended', state = 'default' |
-- 'set' | 'cleared' | 'inactive'}.
local function binding_info(id)
    local record = state.registry[id]
    if not record then return nil end
    if not record.extended then return {backend = 'native', slot = record.slot} end
    local store = load_extended()
    local saved = store.records[id]
    local status = 'default'
    if store.newer or saved and saved.kind == 'unknown' then status = 'inactive'
    elseif saved and saved.kind ~= 'default' then status = saved.kind end
    return {backend = 'extended', state = status}
end

mbm.register_extended, mbm.extended_known, mbm.extended_down = register_extended, extended_known, extended_down
mbm.set_binding, mbm.store_alternatives, mbm.binding, mbm.binding_info = set_binding, store_alternatives, binding,
                                                                         binding_info
mbm.input_name, mbm.input_label, mbm.make_input, mbm.input_down = input_name, input_label, make_input, input_down
mbm.engine_down, mbm.engine_any_pressed, mbm.window_focused = engine_down, engine_any_pressed, window_focused
mbm.current_alternatives = current_alternatives
mbm.EXTENDED_DEVICES, mbm.EXTENDED_TRIGGERS, mbm.DEVICE_KEYS = EXTENDED_DEVICES, EXTENDED_TRIGGERS, DEVICE_KEYS

-- Machine code: only the per-frame evaluation (extended_down,
-- alternative_fires, input_down, engine_down, button_down, connected_pads) may
-- be compiled; registration, lookups, the capture's reads and the file run
-- interpreted.
if type(jit) == 'table' and type(jit.off) == 'function' then
    for _, fn in ipairs({usable, engine_source, device_any_pressed, engine_any_pressed, window_focused, spec_names,
                         spec_alternative, parse_spec, default_alternatives, make_input, resolve_spec,
                         runtime_alternatives, resolve, sort_extended, register_extended, extended_known,
                         set_binding, store_alternatives, current_alternatives, engine_text, input_name,
                         input_label, binding, binding_info}) do
        jit.off(fn)
    end
end
end
mbm_files.extended_store = function(...)
-- Mod Bindings Menu's extended bindings file: the keys the player chose for
-- bindings that have no native action (src/extended.lua), saved safely.
-- src/mod_bindings_menu.lua runs this file once as mbm_files.extended_store(mbm);
-- it adds load_extended, flush_extended, parse_extended, extended_text and
-- EXTENDED_FORMAT to mbm.
--
-- The file, ModBindingsMenu.bindings beside the assignments file, holds one
-- record per line and is only ever parsed as data:
--   format 1
--   <id>\tset\t<alternative>|<alternative>...   the player's binding
--   <id>\tcleared                               the player removed every key:
--                                               the author's default is not used
--   <id>\tdefault                               the author's default applies
--   end                                         a complete file always ends with it
-- An alternative is <input>(+<input>)*@<trigger>: the first input is the one
-- that triggers, each +input must be held with it (modifiers). An input is
-- <device>:<index>, device k (keyboard), m (mouse) or p (controller) and index
-- the engine's button index on that device; trigger press, release or hold.
-- Every extended binding has a line, so an id stays extended in later sessions
-- even when a native action is free then: a binding never changes backend.
--
-- Safety. A line this version cannot read (another device, trigger or verb,
-- written by a newer version) is kept verbatim and written back; its binding
-- stays inactive and is never replaced by its default. A file of a newer format
-- is not changed at all, and every extended binding stays inactive. A damaged
-- file (no end line) is replaced by its backup when that is usable; without
-- one it is set aside as <file>.damaged before the next save, never
-- overwritten. Saves go through <file>.tmp and keep the previous file as
-- <file>.bak (src/assignments.lua's replace_file).
local mbm = ...
local state, note = mbm.state, mbm.note
local settings_path, replace_file, file_exists, SAVE_RETRY = mbm.settings_path, mbm.replace_file, mbm.file_exists,
                                                            mbm.SAVE_RETRY

local EXTENDED_FILE = 'ModBindingsMenu.bindings'
local FORMAT = 1
-- Sanity limits of the parser; none of them limits how many bindings exist.
local MAX_TEXT, MAX_LINE, MAX_ALTERNATIVES, MAX_INPUTS = 4 * 1024 * 1024, 4096, 16, 5
local DEVICES = {k = true, m = true, p = true}
local TRIGGERS = {press = true, release = true, hold = true}

local function extended_path() return settings_path(EXTENDED_FILE) end

-- An alternative from its text, or nil when this version cannot read it.
local function parse_alternative(text)
    local inputs_text, trigger = text:match('^([^@]+)@(%a+)$')
    if not inputs_text or not TRIGGERS[trigger] then return nil end
    local inputs = {}
    for input in (inputs_text .. '+'):gmatch('([^+]*)%+') do
        local device, index = input:match('^(%a):(%d+)$')
        if not device or not DEVICES[device] or #inputs >= MAX_INPUTS then return nil end
        index = tonumber(index)
        if index > 65535 then return nil end
        inputs[#inputs + 1] = {device = device, index = index}
    end
    if #inputs == 0 then return nil end
    return {inputs = inputs, trigger = trigger}
end

local function alternative_text(alternative)
    local parts = {}
    for index, input in ipairs(alternative.inputs) do parts[index] = input.device .. ':' .. input.index end
    return table.concat(parts, '+') .. '@' .. alternative.trigger
end

-- A record from a line: {kind = 'set', alternatives}, {kind = 'cleared'},
-- {kind = 'default'} or {kind = 'unknown', line}; nil for a line without an id.
local function parse_record(line)
    local id, verb, rest = line:match('^([^\t]+)\t(%a+)\t?(.*)$')
    if not id then return nil end
    if (verb == 'cleared' or verb == 'default') and rest == '' then return id, {kind = verb} end
    if verb == 'set' and #line <= MAX_LINE then
        local alternatives = {}
        for part in (rest .. '|'):gmatch('([^|]*)|') do
            local alternative = parse_alternative(part)
            if not alternative or #alternatives >= MAX_ALTERNATIVES then
                return id, {kind = 'unknown', line = line}
            end
            alternatives[#alternatives + 1] = alternative
        end
        if #alternatives > 0 then return id, {kind = 'set', alternatives = alternatives} end
    end
    return id, {kind = 'unknown', line = line}
end

local function new_store()
    return {records = {}, format = FORMAT, dirty = false, failed = false, retry = 0, damaged = false,
            set_aside = false, newer = false}
end

-- The store in text: a store, or nil and 'damaged' (cut short, no format line,
-- too long) or 'newer' (a later format, kept as it is).
local function parse_extended(text)
    if #text > MAX_TEXT then return nil, 'damaged' end
    local lines = text:gmatch('[^\r\n]+')
    local format = tonumber((lines() or ''):match('^format (%d+)$'))
    if not format then return nil, 'damaged' end
    if format > FORMAT then return nil, 'newer' end
    local store = new_store()
    -- Lines after 'end' are ignored; without it the file was cut short.
    for line in lines do
        if line == 'end' then return store end
        local id, record = parse_record(line)
        if id then store.records[id] = record end
    end
    return nil, 'damaged'
end

-- The file's text for store: sorted by id, unknown lines verbatim.
local function extended_text(store)
    local ids = {}
    for id in pairs(store.records) do ids[#ids + 1] = id end
    table.sort(ids)
    local lines = {'format ' .. FORMAT}
    for _, id in ipairs(ids) do
        local record = store.records[id]
        if record.kind == 'unknown' then
            lines[#lines + 1] = record.line
        elseif record.kind == 'cleared' or record.kind == 'default' then
            lines[#lines + 1] = id .. '\t' .. record.kind
        else
            local parts = {}
            for index, alternative in ipairs(record.alternatives) do parts[index] = alternative_text(alternative) end
            lines[#lines + 1] = id .. '\tset\t' .. table.concat(parts, '|')
        end
    end
    lines[#lines + 1] = 'end'
    return table.concat(lines, '\n') .. '\n'
end

local function read_text(path)
    local file = io.open(path, 'rb')
    if not file then return nil end
    local text = file:read('*a')
    file:close()
    if not text or text == '' then return nil end
    return text
end

-- Loads the file once per session: the file, else its backup (written back at
-- the next save), else a new store. state.extended_store = {records, text = the
-- file as read or last written, dirty, failed, retry, damaged = only the backup
-- is usable, set_aside = a damaged file without backup is moved away before the
-- next save, newer = a later format: never written}.
-- The store when the file (text, nil when missing) cannot be used: its
-- backup, else a new store; a damaged file is then set aside at the next save.
local function fallback_store(path, text)
    local backup = path and read_text(path .. '.bak')
    local store = backup and parse_extended(backup)
    if store then
        store.dirty, store.damaged = true, text ~= nil
        note('Extended bindings restored from ' .. EXTENDED_FILE .. '.bak; the file was ' ..
             (text and 'damaged.' or 'missing.'))
        return store
    end
    store = new_store()
    if text then
        store.set_aside = true
        note('The extended bindings file is damaged and has no usable backup; it will be kept as ' ..
             EXTENDED_FILE .. '.damaged, and extended bindings start from their defaults.')
    end
    return store
end

local function load_extended()
    if state.extended_store then return state.extended_store end
    local path, store, problem = extended_path(), nil, nil
    local text = path and read_text(path)
    if text then store, problem = parse_extended(text) end
    if store then
        store.text = text
    elseif problem == 'newer' then
        store = new_store()
        store.newer = true
        note('The extended bindings file was written by a newer Mod Bindings Menu; it is left as it is, and ' ..
             'extended bindings stay inactive.')
    else
        store = fallback_store(path, text)
    end
    state.extended_store = store
    return store
end

-- Saves a changed store, from the step. Unchanged stores are not written; a
-- failed save keeps the changes, logs once, shows on the page (state.save_problem)
-- and is tried again SAVE_RETRY seconds later. A newer-format file is never written.
-- Writes text to path, a damaged file set aside first: true, or false and why.
local function write_store(store, path, text)
    if not path then return false, 'no settings folder' end
    if store.set_aside then
        -- An earlier .damaged file is kept too: this one gets a name of its own.
        local moved = not file_exists(path) or os.rename(path, path .. '.damaged')
                      or os.rename(path, path .. '.damaged-' .. os.time())
        if not moved then return false, 'cannot set the damaged file aside' end
        store.set_aside = false
    end
    return replace_file(path, text, store.damaged)
end

local function save_failed(store, problem)
    store.retry = SAVE_RETRY
    state.save_problem = tostring(problem)
    if store.failed then return end
    store.failed = true
    note('Cannot save extended bindings (' .. tostring(problem) .. '); keeping them and trying again in ' ..
         SAVE_RETRY .. ' seconds.')
end

local function flush_extended(seconds)
    local store = state.extended_store
    if not store or not store.dirty then return end
    if store.newer then
        store.dirty = false
        return
    end
    if store.retry > 0 then
        store.retry = store.retry - seconds
        return
    end
    local text = extended_text(store)
    local saved, problem = text == store.text, nil
    if not saved then saved, problem = write_store(store, extended_path(), text) end
    if not saved then
        save_failed(store, problem)
        return
    end
    if store.failed then note('Saved extended bindings after an earlier failure.') end
    store.text, store.dirty, store.failed, store.damaged = text, false, false, false
    state.save_problem = nil
end

mbm.load_extended, mbm.flush_extended, mbm.parse_extended, mbm.extended_text = load_extended, flush_extended,
                                                                             parse_extended, extended_text
mbm.parse_alternative, mbm.alternative_text, mbm.EXTENDED_FORMAT, mbm.EXTENDED_FILE = parse_alternative,
    alternative_text, FORMAT, EXTENDED_FILE
mbm.MAX_ALTERNATIVES, mbm.MAX_INPUTS = MAX_ALTERNATIVES, MAX_INPUTS
end
mbm_files.panel = function(...)
-- Mod Bindings Menu's panel for extended bindings: the binding pages' fifth
-- tab (MORE MODS), drawn with stingray.Gui inside the game's own list.
-- src/mod_bindings_menu.lua runs this file once as mbm_files.panel(mbm); it
-- adds panel_frame, panel_hide and panel_version to mbm.
--
-- Why a tab of its own: the game's list scrolls only over its own rows (97 at
-- most, each needing a native action), so an unlimited number of rows needs
-- scrolling of its own. The tab's native list holds one section header row;
-- the panel draws every extended binding below it, grouped under its mod's
-- header, and scrolls by whole rows (no clipping needed). Only visible rows
-- are drawn, with retained Gui primitives updated only when something shown
-- changes.
--
-- Geometry: the list viewport (listing+272) and the header row (listing+7856)
-- are native widgets whose solved screen rectangles the game keeps at +148
-- (x) and +156 (y, the bottom edge; y grows upward, as in a screen Gui), +36
-- and +40 (size in UI units) times the scale at +100 and +140, with +84 the
-- inherited opacity and flag 0x10 at +0 while visible (the game's hit test
-- 0x144d320 reads the same fields; Know Your Constellation draws from them).
-- The panel draws only while both are visible, opaque and sane, from the
-- header row's bottom edge to the viewport's, across the header row's width.
--
-- Input: the game's UI actions (group 0 of the input owner's action states:
-- 1 up and 2 down pressed, 5 and 6 up and down held with the game's repeat,
-- 10 select), so navigation follows the player's UI bindings on every device;
-- the cursor of the menu system (its widget at menu+1520, position at +620
-- while it is attached to the root, as the list's own hover test reads it);
-- wheel notches and the left button from stingray.Mouse. Select on a row (a
-- click selects the row under the cursor) starts a key capture
-- (src/capture.lua). While it runs, every active UI action is consumed each
-- frame through the game's consume routine (Clickable Scrollbars consumes
-- select the same way), so Back, tab switching and the rest of the page
-- ignore the keys being captured: Back cancels only the capture.
--
-- Cost: nothing off this tab. On it, per frame: 7 reads (the page kind, both
-- widgets, the menu pointer and the cursor, the input owner and 11 UI action
-- states) and one engine button read (the left button; two more for the wheel
-- while the cursor is over the panel); Gui calls only on a change. During a
-- capture instead: 5 reads (the page kind, both widgets, the input owner and
-- 97 UI action states), a consume call per active UI action and the capture's
-- own engine reads. Once a second the UI world is checked (one engine table).
-- Unmeasured in game.
local mbm = ...
local ffi = require('ffi')
local bit = require('bit')
local state, note, read_into = mbm.state, mbm.note, mbm.read_into

local VIEWPORT, HEADER_ROW, CONTROLLER_PAGE = 272, 7856, 2411904
local WIDGET_BYTES = 164
local CURSOR, CURSOR_PARENT, CURSOR_BYTES, ROOT_A, ROOT_B = 1528, 512, 116, 360, 656
local UI_ACTIONS, UI_GROUP_ACTIONS, STATE_STRIDE = 11, 97, 32
local UP, DOWN, UP_HELD, DOWN_HELD, SELECT = 1, 2, 5, 6, 10
local FONT_RVA, MATERIAL_PTR_RVA, ATLAS_RVA = 0x312d998, 0x3180c08, 0x312e618
local WORLD_CHECK = 1
-- UI units at scale 1 (the game's rows are 62 apart).
local PITCH, GAP, PAD, TEXT, ACCENT, BAR, KEY_COLUMN = 62, 3, 24, 22, 4, 6, 0.56
local WHEEL_ROWS = 3
-- Layers sort across every Gui in a world, 0-1023 only (KB war-table-gui-rendering).
local LAYER = {row = 1011, mark = 1012, text = 1013}
-- {alpha, red, green, blue}
local COLOUR = {row = {150, 14, 18, 26}, focus = {225, 44, 52, 64}, header = {210, 6, 8, 12},
                accent = {255, 255, 232, 0}, text = {255, 240, 243, 245}, muted = {255, 128, 136, 144},
                heading = {255, 255, 232, 0}, capture = {255, 255, 232, 0}, track = {120, 60, 68, 80},
                thumb = {220, 200, 206, 212}}
local PAGE_DEVICES = {keyboard = {k = true, m = true}, controller = {p = true}}

local viewport_buffer, row_buffer = ffi.new('MBM_u8[?]', WIDGET_BYTES), ffi.new('MBM_u8[?]', WIDGET_BYTES)
local viewport_f32, viewport_u32 = ffi.cast('float *', viewport_buffer), ffi.cast('MBM_u32 *', viewport_buffer)
local row_f32, row_u32 = ffi.cast('float *', row_buffer), ffi.cast('MBM_u32 *', row_buffer)
local scratch = ffi.new('MBM_u8[?]', CURSOR_BYTES)
local scratch_f32, scratch_u32 = ffi.cast('float *', scratch), ffi.cast('MBM_u32 *', scratch)
local actions = ffi.new('MBM_u8[?]', UI_GROUP_ACTIONS * STATE_STRIDE)
local actions_f32 = ffi.cast('float *', actions)

-- focus is a row index; focus_id the binding it shows, which keeps the focus
-- when rows are added above it.
local panel = {gui = nil, world = nil, font = nil, material = nil, slots = {}, rows = {}, model = nil,
               first = 1, focus = nil, focus_id = nil, hover = nil, cursor_x = nil, cursor_y = nil,
               select_was = false, repeat_last = {0, 0}, world_timer = 0, open_wait = 0, dirty = true,
               page = 'keyboard', left = 0, right = 0, top = 0, bottom = 0, scale = 1, count = 0,
               drawn_phase = nil, drawn_id = nil, drawn_bindings = nil, mouse_ids = nil, fitted = {}}

local function pointer_at(u32, index)
    local value = u32[index] + u32[index + 1] * 4294967296
    if value < 0x10000 or value >= 0x800000000000 then return nil end
    return value
end

-- A widget's solved rectangle (y up) and scale, or nil unless it is visible,
-- opaque and sane.
local function solved(f32, u32)
    if bit.band(u32[0], 0x10) == 0 then return nil end
    local opacity, sx, sy = f32[21], f32[25], f32[35]
    if not (opacity >= 0.995 and opacity <= 1.01) or not (sx >= 0.3 and sx <= 4) or math.abs(sx - sy) > 0.01 then
        return nil
    end
    local x, y, w, h = f32[37], f32[39], f32[9] * sx, f32[10] * sy
    if not (x >= -16384 and x <= 32768 and y >= -16384 and y <= 32768 and w > 0 and w <= 32768
            and h > 0 and h <= 32768) then
        return nil
    end
    return x, y, x + w, y + h, sx
end

-- The panel's area from the native widgets; false when it cannot be drawn.
-- Marks the panel dirty when the area, the scale or the page kind changed.
local function read_geometry(listing)
    if not read_into(listing + CONTROLLER_PAGE, scratch, 4) then return false end
    local page = scratch_u32[0] ~= 0 and 'controller' or 'keyboard'
    if not read_into(listing + VIEWPORT, viewport_buffer, WIDGET_BYTES)
       or not read_into(listing + HEADER_ROW, row_buffer, WIDGET_BYTES) then
        return false
    end
    local _, bottom, _, _, scale = solved(viewport_f32, viewport_u32)
    local left, top, right = solved(row_f32, row_u32)
    if not bottom or not left or top - bottom < PITCH * scale then return false end
    if left ~= panel.left or right ~= panel.right or top ~= panel.top or bottom ~= panel.bottom
       or scale ~= panel.scale or page ~= panel.page then
        panel.left, panel.right, panel.top, panel.bottom, panel.scale = left, right, top, bottom, scale
        panel.page, panel.dirty = page, true
        panel.count = math.floor((top - bottom) / (PITCH * scale))
        return 'moved'
    end
    return true
end

local function binding_row(index)
    local row = panel.rows[index]
    return row ~= nil and row.record ~= nil
end

local function last_first()
    return math.max(1, #panel.rows - panel.count + 1)
end

local function scroll_to(first)
    first = math.max(1, math.min(last_first(), first))
    if first ~= panel.first then panel.first, panel.dirty = first, true end
end

local function show_focus()
    local focus = panel.focus
    if not focus then return end
    if focus < panel.first then
        -- Keep the section header above the first binding in view.
        scroll_to(binding_row(focus - 1) and focus or focus - 1)
    elseif focus > panel.first + panel.count - 1 then
        scroll_to(focus - panel.count + 1)
    end
end

-- The rows changed or the area did: the scroll stays within the rows, the focus in view.
local function settle()
    scroll_to(panel.first)
    show_focus()
end

local function set_focus(index)
    if index == panel.focus then return end
    panel.focus, panel.dirty = index, true
    panel.focus_id = index and panel.rows[index].record.id or nil
end

-- Rows: a header per category, then its bindings (state.extended_order is
-- sorted by category, then registration). The focus follows its binding.
local function build_model()
    local rows, last, focus = {}, nil, nil
    for _, record in ipairs(state.extended_order) do
        if record.category ~= last then
            rows[#rows + 1] = {header = true, text = record.category}
            last = record.category
        end
        rows[#rows + 1] = {record = record}
        if record.id == panel.focus_id then focus = #rows end
    end
    panel.rows, panel.model, panel.dirty, panel.focus = rows, state.revision, true, focus
    if not focus then panel.focus_id = nil end
    settle()
end

-- Moves the focus to the next binding row in direction step (1 or -1).
local function move_focus(step)
    local index = panel.focus or (step > 0 and 0 or #panel.rows + 1)
    repeat index = index + step until index < 1 or index > #panel.rows or binding_row(index)
    if index >= 1 and index <= #panel.rows then
        set_focus(index)
        show_focus()
    end
end

-- The input owner pointer, and its first count UI action states read into
-- actions; nil when either cannot be read.
local function read_actions(count)
    if not read_into(state.base + mbm.INPUT_OWNER_PTR_RVA, scratch, 8) then return nil end
    local owner = pointer_at(scratch_u32, 0)
    if not owner or not read_into(owner + mbm.ACTION_STATE_OFFSET, actions, count * STATE_STRIDE) then
        return nil
    end
    return owner
end

local function active(index) return actions[index * STATE_STRIDE] ~= 0 end

-- The game's held repeat (0x178dc50): fires on the press, then after half a
-- second held every 0.1 s (an analog stick part-way: up to every second).
local function repeated(index, slot)
    local held = actions_f32[index * 8 + 2]
    if active(index) then
        panel.repeat_last[slot] = held
        return true
    end
    if held <= 0.5 then return false end
    local magnitude = math.min(1, math.abs(actions_f32[index * 8 + 1]))
    if held - panel.repeat_last[slot] <= magnitude * 0.1 + (1 - magnitude) then return false end
    panel.repeat_last[slot] = held
    return true
end

local function navigate()
    if active(UP) or repeated(UP_HELD, 1) then move_focus(-1) end
    if active(DOWN) or repeated(DOWN_HELD, 2) then move_focus(1) end
end

-- The cursor position (y up), or nil while it is not attached to the root.
local function cursor()
    if not read_into(state.base + mbm.MENU_SYSTEM_PTR_RVA, scratch, 8) then return nil end
    local menu = pointer_at(scratch_u32, 0)
    if not menu or not read_into(menu + CURSOR + CURSOR_PARENT, scratch, CURSOR_BYTES) then return nil end
    local parent = pointer_at(scratch_u32, 0)
    if parent ~= menu + ROOT_A and parent ~= menu + ROOT_B then return nil end
    return scratch_f32[27], scratch_f32[28]
end

-- The binding row under the cursor, or nil.
local function row_at(x, y)
    if not x or x < panel.left or x > panel.right or y > panel.top or y < panel.bottom then return nil end
    local index = panel.first + math.floor((panel.top - y) / (PITCH * panel.scale))
    if index > panel.first + panel.count - 1 or not binding_row(index) then return nil end
    return index
end

-- The cursor: whether it is over the panel, the binding row under it (which
-- takes the focus when the cursor moves onto it).
local function track_cursor()
    local x, y = cursor()
    local moved = x ~= panel.cursor_x or y ~= panel.cursor_y
    panel.cursor_x, panel.cursor_y = x, y
    panel.inside = x ~= nil and x >= panel.left and x <= panel.right and y <= panel.top and y >= panel.bottom
    local hover = row_at(x, y)
    if hover ~= panel.hover then panel.hover, panel.dirty = hover, true end
    if moved and hover then set_focus(hover) end
end

local function mouse_ids(mouse)
    if panel.mouse_ids == nil then
        local ids = {}
        for _, name in ipairs({'left', 'wheel_up', 'wheel_down'}) do
            local ok, id = pcall(mouse.button_id, name)
            ids[name] = ok and type(id) == 'number' and id or false
        end
        panel.mouse_ids = ids
    end
    return panel.mouse_ids
end

local function mouse_pressed(mouse, id)
    if not id or type(mouse.pressed) ~= 'function' then return false end
    local ok, pressed = pcall(mouse.pressed, id)
    return ok and pressed == true
end

-- The capture's hooks: while it runs, the panel consumes UI actions.
local hooks = {hold_back = function() panel.guarding = true end,
               release_back = function() panel.guarding = false end}

local function start_capture(index)
    local row = panel.rows[index]
    if not row or not row.record then return end
    set_focus(index)
    local ok, why = mbm.begin_capture(row.record.id, hooks, panel.page)
    if not ok then note('Key capture for ' .. row.record.id .. ' not started: ' .. tostring(why) .. '.') end
end

-- One frame of the panel's own input, without a capture running. A click
-- starts a capture on the row under the cursor (a click elsewhere does
-- nothing); select from the keyboard or a controller, on the focused row.
local function handle_input(mouse)
    navigate()
    track_cursor()
    local ids = type(mouse) == 'table' and mouse_ids(mouse)
    if ids and panel.inside then
        if mouse_pressed(mouse, ids.wheel_up) then scroll_to(panel.first - WHEEL_ROWS) end
        if mouse_pressed(mouse, ids.wheel_down) then scroll_to(panel.first + WHEEL_ROWS) end
    end
    local select = active(SELECT)
    local rising = select and not panel.select_was
    panel.select_was = select
    if ids and mouse_pressed(mouse, ids.left) then
        if panel.hover then start_capture(panel.hover) end
    elseif rising and panel.focus then
        start_capture(panel.focus)
    end
end

-- While a capture runs: every active UI action of the frame is consumed, so
-- the page does not act on the keys being captured.
local function guard_page()
    local owner = read_actions(UI_GROUP_ACTIONS)
    if not owner or not mbm.consume_action then return end
    for index = 0, UI_GROUP_ACTIONS - 1 do
        if active(index) then
            local ok, problem = pcall(mbm.consume_action, owner, index * 4294967296)
            if not ok then note('Consuming UI action ' .. index .. ' failed: ' .. tostring(problem)) end
        end
    end
end

-- Texts ----------------------------------------------------------------------

local function row_label(record)
    if record.text then return record.text end
    -- A game localization ID cannot be shown outside the native rows: the
    -- binding's id stands in, e.g. 'example.toggle_hud' -> 'TOGGLE HUD'.
    local name = record.id:match('([^%.:/]+)$') or record.id
    return mbm.upper((name:gsub('[_%-]+', ' ')))
end

local function alternative_text(alternative)
    local names = {}
    for position = #alternative.inputs, 1, -1 do
        names[#names + 1] = mbm.input_label(alternative.inputs[position])
    end
    return table.concat(names, ' + ')
end

-- A binding's keys on this page, and the colour to show them in.
local function keys_text(record)
    local info = mbm.binding_info(record.id)
    if info and info.state == 'inactive' then return mbm.text('binding.inactive'), COLOUR.muted end
    local parts, devices = {}, PAGE_DEVICES[panel.page]
    for _, alternative in ipairs(mbm.current_alternatives(record.id) or {}) do
        if devices[alternative.inputs[1].device] then parts[#parts + 1] = alternative_text(alternative) end
    end
    if #parts == 0 then return mbm.text('binding.none'), COLOUR.muted end
    return mbm.upper(table.concat(parts, ' / ')), COLOUR.text
end

-- A binding row's texts and colours: its label and keys, or while its key is
-- being chosen the page's hint and prompt.
local function row_texts(record)
    local phase, id = mbm.capture_phase()
    if phase ~= 'idle' and id == record.id then
        local pad = panel.page == 'controller' and '_pad' or ''
        return mbm.text('binding.capture_hint' .. pad), COLOUR.muted, mbm.text('binding.capture' .. pad),
               COLOUR.capture
    end
    local keys, keys_colour = keys_text(record)
    return row_label(record), COLOUR.text, keys, keys_colour
end

-- Gui ------------------------------------------------------------------------

local function engine() return rawget(_G, 'stingray') end

local function ui_world(application)
    local main = application.main_world()
    for _, world in ipairs(application.worlds()) do
        if world ~= main then return world end
    end
    return nil
end

local function world_alive(application, world)
    for _, candidate in ipairs(application.worlds()) do
        if candidate == world then return true end
    end
    return false
end

local function hash_at(address)
    if not read_into(address, scratch, 8) then return nil end
    if scratch_u32[0] == 0 and scratch_u32[1] == 0 then return nil end
    return string.format('%08x%08x', scratch_u32[1], scratch_u32[0])
end

-- The active language's body font, its normal material and atlas (the native
-- font initializer keeps them there; Know Your Constellation reads the same).
local function font_hashes()
    local font, atlas = hash_at(state.base + FONT_RVA), hash_at(state.base + ATLAS_RVA)
    if not read_into(state.base + MATERIAL_PTR_RVA, scratch, 8) then return nil end
    local material_owner = pointer_at(scratch_u32, 0)
    local material = material_owner and hash_at(material_owner + 24)
    if not (font and atlas and material) then return nil end
    return font, material, atlas
end

-- Mirrors the native normal-font setup on the Gui's material.
local function ink(e, gui, material_hash, atlas_hash)
    local material = assert(e.Gui.material(gui, e.IdString64.from_hex(material_hash)), 'font material unavailable')
    local function slot(hash) return e.IdString64.from_hex(hash .. '00000000') end
    for _, hash in ipairs({'8035c266', '5e8455fe', '309e7783', '82b803a8'}) do
        e.Material.set_scalar(material, slot(hash), 0)
    end
    e.Material.set_vector2(material, slot('e13777ce'), e.Vector2(1, -1))
    e.Material.set_vector4(material, slot('7701209e'), e.Color(0, 0, 0, 0))
    e.Material.set_texture(material, slot('88bac99b'), e.IdString64.from_hex(atlas_hash))
end

-- Creates the Gui; after a failure the next try waits WORLD_CHECK seconds.
local function open_gui(e, seconds)
    panel.open_wait = panel.open_wait - seconds
    if panel.open_wait > 0 then return false end
    panel.open_wait = WORLD_CHECK
    local font, material, atlas = font_hashes()
    local world = font and ui_world(e.Application)
    if not world then return false end
    local ok, gui = pcall(e.World.create_screen_gui, world, 'scale', 1, 1)
    if not ok or not gui then
        note('Panel: no screen Gui (' .. tostring(gui) .. ').')
        return false
    end
    panel.gui, panel.world, panel.font, panel.material, panel.slots = gui, world, font, material, {}
    panel.world_timer, panel.open_wait, panel.dirty, panel.fitted = 0, 0, true, {}
    local inked, problem = pcall(ink, e, gui, material, atlas)
    if not inked then note('Panel: font material not set (' .. tostring(problem) .. ').') end
    return true
end

local function close_gui()
    local gui, world = panel.gui, panel.world
    panel.gui, panel.world, panel.slots, panel.dirty = nil, nil, {}, true
    panel.drawn_phase, panel.drawn_id, panel.drawn_bindings = nil, nil, nil
    if not gui then return end
    local e = engine()
    local ok, problem = pcall(function()
        if world_alive(e.Application, world) then e.World.destroy_gui(world, gui) end
    end)
    if not ok then note('Panel: destroying its Gui failed (' .. tostring(problem) .. ').') end
end

-- The engine while drawing (draw sets it), and each shape's {layer, colour}.
local E
local STYLE = {row = {LAYER.row, COLOUR.row}, focus = {LAYER.row, COLOUR.focus}, header = {LAYER.row, COLOUR.header},
               accent = {LAYER.mark, COLOUR.accent}, track = {LAYER.row, COLOUR.track},
               thumb = {LAYER.mark, COLOUR.thumb}}

local function colour(c) return E.Color(c[1], c[2], c[3], c[4]) end

-- One retained rectangle: created on first use, updated after; a zero size hides it.
local function rect(slot, key, x, y, w, h, style)
    local position, size = E.Vector3(x, y, style[1]), E.Vector2(w, h)
    if slot[key] then
        E.Gui.update_rect(panel.gui, slot[key], position, size, colour(style[2]))
    else
        slot[key] = E.Gui.rect(panel.gui, position, size, colour(style[2]))
    end
end

-- One retained text: created on first use (an empty one as a space), updated after.
local function text(slot, key, value, x, y, size, c)
    local font, material = E.IdString64.from_hex(panel.font), E.IdString64.from_hex(panel.material)
    local position = E.Vector3(x, y, LAYER.text)
    if slot[key] then
        E.Gui.update_text(panel.gui, slot[key], value, font, size, material, position, colour(c))
    else
        slot[key] = E.Gui.text(panel.gui, value == '' and ' ' or value, font, size, material, position, colour(c))
    end
end

-- Whether value is wider than width at size in the Gui's font (the same
-- measure as Know Your Constellation's).
local function too_wide(value, size, width)
    local lo, hi, caret = E.Gui.text_extents(panel.gui, value, E.IdString64.from_hex(panel.font), size)
    local x = E.Vector2.x
    return math.max(x(hi), x(caret)) - math.min(0, x(lo)) > width
end

-- The longest start of value, whole characters and '...', that fits width;
-- value itself when it fits or the engine cannot measure. Cached per text,
-- size and width (measured on redraws only).
local function fit(value, size, width)
    if value == '' or type(E.Gui.text_extents) ~= 'function' then return value end
    local key = value .. '\0' .. size .. '\0' .. width
    local cached = panel.fitted[key]
    if cached then return cached end
    local ok, wide = pcall(too_wide, value, size, width)
    local result = value
    if ok and wide then
        local starts = {}
        for position in value:gmatch('()[^\128-\191]') do starts[#starts + 1] = position end
        local low, high = 0, #starts - 1
        while low < high do
            local middle = math.ceil((low + high) / 2)
            local fits, wider = pcall(too_wide, value:sub(1, starts[middle + 1] - 1) .. '...', size, width)
            if fits and not wider then low = middle else high = middle - 1 end
        end
        result = value:sub(1, (starts[low + 1] or #value + 1) - 1) .. '...'
    end
    panel.fitted[key] = result
    return result
end

local function hide_slot(slot)
    if not slot.bg then return end
    for _, key in ipairs({'bg', 'mark'}) do rect(slot, key, 0, 0, 0, 0, STYLE.row) end
    for _, key in ipairs({'label', 'keys'}) do text(slot, key, '', 0, 0, 1, COLOUR.text) end
end

-- Draws row index into slot n (0 at the top).
local function draw_slot(slot, n, index)
    local s, row = panel.scale, panel.rows[index]
    local pitch = PITCH * s
    local top = panel.top - n * pitch
    local x, width = panel.left, panel.right - panel.left - (BAR + GAP) * s
    local bottom, height = top - pitch + GAP * s, pitch - 2 * GAP * s
    local baseline, size = top - pitch / 2 - TEXT * s * 0.35, TEXT * s
    if row.header then
        rect(slot, 'bg', x, bottom, width, height, STYLE.header)
        rect(slot, 'mark', 0, 0, 0, 0, STYLE.accent)
        text(slot, 'label', fit(row.text, size, width - 2 * PAD * s), x + PAD * s, baseline, size, COLOUR.heading)
        text(slot, 'keys', '', 0, 0, size, COLOUR.text)
        return
    end
    local focused = index == panel.focus or index == panel.hover
    local column = width * KEY_COLUMN
    rect(slot, 'bg', x, bottom, width, height, focused and STYLE.focus or STYLE.row)
    rect(slot, 'mark', x, bottom, focused and ACCENT * s or 0, height, STYLE.accent)
    local label, label_colour, keys, keys_colour = row_texts(row.record)
    text(slot, 'label', fit(label, size, column - 2 * PAD * s), x + PAD * s, baseline, size, label_colour)
    text(slot, 'keys', fit(keys, size, width - column - PAD * s), x + column, baseline, size, keys_colour)
end

local function draw_scrollbar()
    local slot = panel.slots.bar or {}
    panel.slots.bar = slot
    local s, total = panel.scale, #panel.rows
    if total <= panel.count then
        rect(slot, 'bg', 0, 0, 0, 0, STYLE.track)
        rect(slot, 'mark', 0, 0, 0, 0, STYLE.thumb)
        return
    end
    local x, height = panel.right - BAR * s, panel.top - panel.bottom
    local thumb = math.max(PITCH * s / 2, height * panel.count / total)
    local offset = (height - thumb) * (panel.first - 1) / (total - panel.count)
    rect(slot, 'bg', x, panel.bottom, BAR * s, height, STYLE.track)
    rect(slot, 'mark', x, panel.top - offset - thumb, BAR * s, thumb, STYLE.thumb)
end

local function draw(e)
    E = e
    for n = 0, panel.count - 1 do
        local slot = panel.slots[n + 1] or {}
        panel.slots[n + 1] = slot
        local index = panel.first + n
        if panel.rows[index] then draw_slot(slot, n, index) else hide_slot(slot) end
    end
    for n = panel.count + 1, #panel.slots do hide_slot(panel.slots[n]) end
    draw_scrollbar()
    panel.dirty = false
end

-- Frame ----------------------------------------------------------------------

local function changed_capture()
    local phase, id = mbm.capture_phase()
    if phase ~= panel.drawn_phase or id ~= panel.drawn_id or state.bindings_version ~= panel.drawn_bindings then
        panel.drawn_phase, panel.drawn_id, panel.drawn_bindings, panel.dirty = phase, id, state.bindings_version, true
    end
    return phase ~= 'idle'
end

-- The UI world still exists (checked once a second): a world change closes the Gui.
local function world_ok(e, seconds)
    panel.world_timer = panel.world_timer + seconds
    if panel.world_timer < WORLD_CHECK then return true end
    panel.world_timer = 0
    if world_alive(e.Application, panel.world) then return true end
    panel.gui, panel.world = nil, nil
    return false
end

-- Closes the panel (tab left, page closed, layout unusable, pause or stop):
-- any capture ends with reason, the Gui goes.
local function panel_hide(reason)
    if mbm.capture_phase() ~= 'idle' then mbm.cancel_capture(reason) end
    panel.guarding, panel.select_was = false, false
    if panel.gui then close_gui() end
end

-- The frame's input: a running capture (the page guarded, then its update),
-- else the panel's own navigation, cursor and select.
local function frame_input(e, seconds)
    if changed_capture() then
        -- Consumed actions read as released until they are: select counts
        -- again from its next press.
        panel.select_was = false
        if panel.guarding then guard_page() end
        mbm.update_capture(seconds)
    elseif read_actions(UI_ACTIONS) then
        handle_input(e.Mouse)
    end
    changed_capture()
end

-- One frame with the MORE MODS tab shown and its native list built.
local function panel_frame(listing, seconds)
    local e = engine()
    if type(e) ~= 'table' or type(e.Gui) ~= 'table' or not state.base then return end
    local geometry = read_geometry(listing)
    if not geometry then
        panel_hide('the page layout changed')
        return
    end
    if panel.model ~= state.revision then
        build_model()
    elseif geometry == 'moved' then
        settle()
    end
    frame_input(e, seconds)
    if panel.gui and not world_ok(e, seconds) then return end
    if not panel.gui and not open_gui(e, seconds) then return end
    if panel.dirty then
        local ok, problem = pcall(draw, e)
        if not ok then
            note('Panel: drawing failed (' .. tostring(problem) .. ').')
            panel_hide('drawing failed')
        end
    end
end

mbm.panel_frame, mbm.panel_hide = panel_frame, panel_hide
function mbm.panel_state() return panel end

-- Machine code: the panel runs only on its tab; nothing here is compiled.
if type(jit) == 'table' and type(jit.off) == 'function' then
    for _, fn in ipairs({pointer_at, solved, read_geometry, build_model, binding_row, last_first, scroll_to,
                         show_focus, settle, set_focus, move_focus, read_actions, active, repeated, navigate,
                         cursor, row_at, track_cursor, mouse_ids, mouse_pressed, start_capture, handle_input,
                         guard_page, row_label, alternative_text, keys_text, row_texts, engine, ui_world,
                         world_alive, hash_at, font_hashes, ink, open_gui, close_gui, colour, rect, text,
                         too_wide, fit, hide_slot, draw_slot, draw_scrollbar, draw, changed_capture,
                         frame_input, world_ok, panel_hide, panel_frame, hooks.hold_back, hooks.release_back,
                         mbm.panel_state}) do
        jit.off(fn)
    end
end
end
mbm_files.poll = function(...)
-- Mod Bindings Menu's batch polling: ModBindingsMenu.poll(ids, out) answers
-- several bindings in one call and writes each one's state and its edges into
-- arrays of a table the caller owns (README: "Polling several bindings").
-- src/mod_bindings_menu.lua runs this file once as mbm_files.poll(mbm); it adds
-- poll to mbm.
--
-- out.down[i] is exactly what is_down(ids[i]) would return at that point: the
-- record headers are read and checked one by one, in order, as is_down reads
-- them, so a sweep one of them starts comes before the later headers. Only the
-- input owner and the action states are read once for all: the owner, then one
-- stretch from the lowest to the highest action polled. For n available
-- bindings that is n + 2 reads instead of is_down's 3n, and nothing is
-- allocated once out's arrays hold every position.
local mbm = ...
local ffi, bit = require('ffi'), require('bit')
local state, live_header, active_screen = mbm.state, mbm.live_header, mbm.active_screen
local extended_down = mbm.extended_down
local sweep_bindings, read_words, read_into = mbm.sweep_bindings, mbm.read_words, mbm.read_into
local word_pointer, words = mbm.word_pointer, mbm.words
local INPUT_OWNER_PTR_RVA, STATE_OFFSET, STRIDE = mbm.INPUT_OWNER_PTR_RVA, mbm.ACTION_STATE_OFFSET,
                                                  mbm.ACTION_STATE_STRIDE
local INVALID = 'invalid poll arguments'

-- The dormant actions' state entries (STRIDE bytes each, byte 0 the state) lie
-- in one stretch of the input owner: 9,345 bytes from the first (9:0) to the
-- last (12:1) state byte. A poll reads the part between its own lowest and
-- highest action into span, allocated at the first poll that reads states.
local FIRST, LAST = math.huge, -1
for _, entry in ipairs(mbm.DORMANT_ACTIONS) do
    FIRST, LAST = math.min(FIRST, entry[1] * 97 + entry[2]), math.max(LAST, entry[1] * 97 + entry[2])
end
local span
-- By position in ids: the state entry index this poll reads, or false.
local pending = {}

-- The arrays poll fills, created in out at its first poll. An out whose field
-- is something else is refused before anything is written.
local FIELDS = {'down', 'pressed', 'released', 'last'}
local function arrays(out)
    if type(out) ~= 'table' then return false end
    for _, field in ipairs(FIELDS) do
        if out[field] ~= nil and type(out[field]) ~= 'table' then return false end
    end
    for _, field in ipairs(FIELDS) do
        if out[field] == nil then out[field] = {} end
    end
    return true
end

-- One native binding's record header, checked as is_down checks it: its state
-- entry index, false when its mapping count changed outside the binding pages
-- (the game restored a list: the sweep runs now, and the state is not read),
-- or nil (no binding).
local function header(record)
    local bucket, count = live_header(record)
    if not bucket then return nil end
    if count ~= state.swept_counts[record.code] and not active_screen() then
        sweep_bindings()
        return false
    end
    return record.group * 97 + record.action
end

-- Every header, in order. Sets pending and, for the bindings whose state is
-- not read, down; returns the lowest and highest state index to read (low >
-- high: none) and whether a sweep ran. Extended bindings answer as is_down
-- does; native ones read false while a key capture suppresses mod bindings.
-- One binding's state index to read; else false, its answer now (an extended
-- binding's, false for a native one while mod bindings are suppressed, nil for
-- an unknown id, before native input or for a record not found, false after a
-- sweep) and whether a sweep ran.
local function entry_of(record, ready)
    if record and record.extended then
        if state.unsupported then return false, nil, false end
        return false, extended_down(record), false
    end
    if not (record and ready) then return false, nil, false end
    if state.suppressed then return false, false, false end
    local index = header(record)
    if index then return index end
    return false, index, index == false
end

local function headers(ids, n, down)
    local ready, low, high, swept = state.build_rows ~= nil, LAST, FIRST, false
    for i = 1, n do
        local index, answer, sweep = entry_of(state.registry[ids[i]], ready)
        if index then
            low, high = math.min(low, index), math.max(high, index)
        else
            down[i], swept = answer, swept or sweep
        end
        pending[i] = index
    end
    return low, high, swept
end

-- One pending state: from the stretch when it was read, else on its own, as
-- is_down reads it; nil without the input owner.
local function entry_down(owner, whole, low, index)
    if whole then return span[STRIDE * (index - low)] ~= 0 end
    if owner and read_words(owner + STATE_OFFSET + STRIDE * index, 1) then
        return bit.band(words[0], 0xff) ~= 0
    end
    return nil
end

-- The pending states: the input owner, then the stretch from low to high in
-- one read (each entry on its own should that read fail).
local function read_states(n, down, low, high)
    span = span or ffi.new('MBM_u8[?]', STRIDE * (LAST - FIRST) + 1)
    local owner = read_words(state.base + INPUT_OWNER_PTR_RVA, 8) and word_pointer(0)
    local whole = owner and read_into(owner + STATE_OFFSET + STRIDE * low, span, STRIDE * (high - low) + 1)
    for i = 1, n do
        local index = pending[i]
        if index then down[i] = entry_down(owner, whole, low, index) end
    end
end

-- Edges against last: the state at the previous poll with this table that
-- trusted its frame (nil and false are up; an unavailable binding counts as
-- up). After a sweep nothing this frame is trusted: no edges, last kept.
local function edges(n, out, trusted)
    local down, pressed, released, last = out.down, out.pressed, out.released, out.last
    for i = 1, n do
        local now, before = down[i] == true, last[i] == true
        if trusted then
            pressed[i], released[i], last[i] = now and not before, before and not now, now
        else
            pressed[i], released[i], last[i] = false, false, before
        end
    end
end

-- ModBindingsMenu.poll(ids, out): true once out.down, out.pressed,
-- out.released and out.last hold positions 1 to #ids, or false and a reason.
function mbm.poll(ids, out)
    if type(ids) ~= 'table' or not arrays(out) then return false, INVALID end
    local n, down = #ids, out.down
    local low, high, swept = headers(ids, n, down)
    if low <= high then read_states(n, down, low, high) end
    edges(n, out, not swept)
    return true
end

-- Machine code. The loop over the headers is compiled: its branches go the same
-- way on every frame and its reads are FFI calls. Everything else runs once per
-- call or branches on which bindings are down, and compiled it mostly grew side
-- traces. In the game's lua51.dll, two simulated minutes of Ship Station
-- Hotkeys' six bindings read every frame (median of 10 fresh processes) took
-- 24.0 KB of machine code with poll compiled and 11.3 KB with this split, for
-- 4.02 and 4.44 us per frame (test process, the menu's update included); six
-- is_down calls took 14.3 KB and 5.97 us.
if type(jit) == 'table' and type(jit.off) == 'function' then
    for _, fn in ipairs({arrays, entry_down, read_states, edges, mbm.poll}) do jit.off(fn) end
end
end
mbm_files.sweep = function(...)
-- Mod Bindings Menu's binding sweep: what happens to the mappings of the native
-- actions that mod bindings use. src/mod_bindings_menu.lua runs this file once
-- as mbm_files.sweep(mbm); it adds sweep_bindings to mbm.
--
-- The dormant actions ship with developer defaults (controller buttons, the
-- mouse, Enter, Escape...) in the game's input configuration, and saved settings from v1 kept
-- them. They must never fire a mod binding, and a mapping the player chose must
-- never be deleted, even one equal to a developer default. So:
-- - Only actions a binding uses this session are swept. Another mod may use the
--   others natively, and an action whose binding registers late keeps its keys.
-- - The first time a binding uses an action, its mappings equal to one of the
--   action's shipped defaults (Mod Bindings Menu's own keyboard default on the
--   fixed slots aside) are cleared, once. The assignments file records it per
--   action: the session, and fingerprints of the list found and the list left.
-- - Afterwards every list the player makes is kept. Only a list that is exactly
--   the action's shipped defaults, or exactly the list found then, is cleaned
--   again: the game restored it (Revert, a config re-parse, a saved settings
--   file of an older version). After a binding page closes, an action changed
--   into one mapping a capture can make is the player's choice even then,
--   unless other actions were restored with it, indicating a wholesale restore.
-- - An action handed over from an expired binding is cleared entirely.
-- - RepeatInterval button mappings become Press: the page has no selector for
--   RepeatInterval, which repeats while held.
-- - Native Revert copies only the current page's devices from DEFAULTS_MAP.
--   Keep that map free of developer defaults too, retaining the untouched
--   records privately so old saved lists can still be recognized and cleaned.
-- Per two-second sweep: two reads per registered action (live and defaults),
-- no allocation or write when unchanged. The extra defaults read detects a
-- native re-parse; while a binding page is open, defaults alone are checked
-- each frame so Revert always reads the sanitized source. This additional cost
-- is unmeasured in game; gameplay idle/poll frames add no reads.
-- The fixed slots' keyboard defaults (below) add two reads per fixed slot once
-- per session; re-adding them after a re-parse adds no read, only a write.
local mbm = ...
local ffi, bit = require('ffi'), require('bit')
local state, note, load_assignments = mbm.state, mbm.note, mbm.load_assignments
local read_into, map_bucket = mbm.read_into, mbm.map_bucket
local BINDING_MAP, DEFAULTS_MAP, RECORD_SIZE = mbm.BINDING_MAP, mbm.DEFAULTS_MAP, mbm.RECORD_SIZE
local MAPPINGS_OFFSET, MAPPING_SIZE, MAX_MAPPINGS = mbm.MAPPINGS_OFFSET, mbm.MAPPING_SIZE, mbm.MAX_MAPPINGS

-- Fixed slots whose keyboard default is Mod Bindings Menu's own: slot 1 Tab,
-- slots 3-7 F1, F5, F6, F7, F8. Each is the mapping the game's parser made
-- from the content/input replacement releases up to v2.3 shipped (build
-- 25480438, read live): {flags (Keyboard, Button, any device slot, Press,
-- virtual-key code in bits 20-31), key word (49 + virtual-key code)}. They are
-- now added while the game runs (add_keyboard_defaults below).
local SHIPPED_KEYBOARD_DEFAULT = {
    [12 * 65536 + 1] = {0x0090ff43, 0x3a}, [10 * 65536 + 1] = {0x0700ff43, 0xa1},
    [10 * 65536 + 4] = {0x0740ff43, 0xa5}, [10 * 65536 + 8] = {0x0750ff43, 0xa6},
    [10 * 65536 + 14] = {0x0760ff43, 0xa7}, [10 * 65536 + 9] = {0x0770ff43, 0xa8},
}
local KEYBOARD_DEVICE = 3
local BUTTON_INPUT, REPEAT_INTERVAL, PRESS = 4, 8, 0
local FNV_BASIS = bit.tobit(2166136261)

-- The live record and the shipped defaults' record, read in place. A mapping
-- is five 32-bit words from byte 8 + 20 * index: flags (device bits 0-3, input
-- type 4-7, trigger 16-19), key (low half; the config parser leaves bytes 6-7
-- unset), trigger, combine, threshold.
local live, shipped = ffi.new('MBM_u8[?]', RECORD_SIZE), ffi.new('MBM_u8[?]', RECORD_SIZE)
local live_words, shipped_words = ffi.cast('MBM_u32 *', live), ffi.cast('MBM_u32 *', shipped)
local originals = {}
local function at(index) return 2 + index * 5 end

-- FNV-1a over a record's mapping count and every mapping's words, bytes 6-7
-- aside: equal lists of mappings have equal fingerprints.
local function mix(hash, value)
    hash = bit.bxor(hash, value)
    return bit.tobit(hash * 403 + bit.lshift(hash, 24)) -- times 16777619 = 2^24 + 403, modulo 2^32
end
local function fingerprint(words)
    local hash = mix(FNV_BASIS, words[1])
    for index = 0, words[1] - 1 do
        local x = at(index)
        hash = mix(mix(mix(mix(mix(hash, words[x]), bit.band(words[x + 1], 0xffff)), words[x + 2]),
                       words[x + 3]), words[x + 4])
    end
    return hash
end

-- The fixed slots' keyboard defaults, added while the game runs (no game file
-- is replaced), only after the build check passed. For each fixed slot,
-- added[code] holds the fingerprint of the game's stock list (taken from the
-- defaults map, which the game fills only from its own content/input) and the
-- record with the added list: the stock list with its first keyboard mapping
-- replaced by Mod Bindings Menu's (SHIPPED_KEYBOARD_DEFAULT) and any other
-- keyboard mapping dropped, as the replacement file had it. The game puts the
-- stock list back when it re-parses content/input: into the live map on a
-- device change (then its saved input settings follow) and into the defaults
-- map on a settings reset. A record read below that holds exactly the stock
-- list gets the added list again; no read is made for this.
local added = {}
-- The added record for code, from the stock record in words (whole, read in place).
local function derive(code, words)
    local key = SHIPPED_KEYBOARD_DEFAULT[code]
    local entry = {stock = fingerprint(words), record = ffi.new('MBM_u8[?]', RECORD_SIZE), placed = false}
    local out = ffi.cast('MBM_u32 *', entry.record)
    out[0] = words[0]
    local count = 0
    for index = 0, words[1] - 1 do
        local x = at(index)
        local keyboard = bit.band(words[x], 0xf) == KEYBOARD_DEVICE
        if not (keyboard and entry.placed) then
            local y = at(count)
            for word = 0, 4 do out[y + word] = words[x + word] end
            if keyboard then
                out[y], out[y + 1], out[y + 2], entry.placed = key[1], key[2], PRESS, true
            end
            count = count + 1
        end
    end
    out[1] = count
    entry.added = fingerprint(out)
    return entry
end
-- Writes the added list over the game's record at bucket, and over buffer read
-- from it, when the record holds the stock list. Returns whether it wrote.
local writes = 0
local function restore_added(bucket, buffer, words, code, which)
    local entry = added[code]
    if not entry.placed or entry.stock == entry.added or fingerprint(words) ~= entry.stock then return false end
    ffi.copy(buffer + 4, entry.record + 4, RECORD_SIZE - 4)
    ffi.copy(ffi.cast('MBM_u8 *', bucket) + 4, entry.record + 4, RECORD_SIZE - 4)
    writes = writes + 1
    if entry.ready then
        note(string.format('Added the keyboard default of %d:%d again: the game restored its stock list (%s).',
                           math.floor(code / 65536), code % 65536, which))
    end
    return true
end

-- Reads code's record from a binding map into buffer, whole: its cached address
-- (one read), else the map is indexed again. Returns the record's address.
-- A fixed slot's record holding the stock list gets the added list first.
local function read_record(map_offset, cache, code, buffer, words)
    local bucket = cache[code]
    for _ = 1, 2 do
        if bucket and read_into(bucket, buffer, RECORD_SIZE) and words[0] == code and words[1] <= MAX_MAPPINGS then
            if added[code] then
                restore_added(bucket, buffer, words, code, map_offset == DEFAULTS_MAP and 'reset defaults' or 'live')
            end
            return bucket
        end
        cache[code] = nil
        bucket = map_bucket(map_offset, code, cache)
    end
    return nil
end

-- Once per session, when native input is ready (after the build check): the
-- stock list of each fixed slot from the defaults map, then both maps get the
-- added list where they hold the stock one. Live records the game's saved
-- input settings already changed are left alone. Two reads per fixed slot;
-- a slot whose records cannot be read yet is retried by the next sweep.
local function add_keyboard_defaults()
    local pending, before = false, writes
    for code in pairs(SHIPPED_KEYBOARD_DEFAULT) do
        if not added[code] then
            local bucket = read_record(DEFAULTS_MAP, state.default_buckets, code, live, live_words)
            if bucket then
                local entry = derive(code, live_words)
                added[code] = entry
                if not entry.placed then
                    note(string.format('Fixed slot action %d:%d has no keyboard mapping; its default is not added.',
                                       math.floor(code / 65536), code % 65536))
                end
                restore_added(bucket, live, live_words, code)
                -- The live record: read_record writes the added list when it holds the stock one.
                read_record(BINDING_MAP, state.buckets, code, shipped, shipped_words)
                entry.ready = true
            else
                pending = true
            end
        end
    end
    state.keyboard_pending = pending
    if writes > before then
        note('Added Mod Bindings Menu\'s keyboard defaults to ' .. (writes - before) .. ' binding records.')
    end
end

local function same_mapping(a, a_index, b, b_index)
    local x, y = at(a_index), at(b_index)
    return a[x] == b[y] and bit.band(a[x + 1], 0xffff) == bit.band(b[y + 1], 0xffff)
        and a[x + 2] == b[y + 2] and a[x + 3] == b[y + 3] and a[x + 4] == b[y + 4]
end

-- Whether live mapping index is one of the action's shipped developer defaults.
local function inherited(code, index)
    for other = 0, shipped_words[1] - 1 do
        local own = SHIPPED_KEYBOARD_DEFAULT[code] and bit.band(shipped_words[at(other)], 0xf) == KEYBOARD_DEVICE
        if not own and same_mapping(live_words, index, shipped_words, other) then return true end
    end
    return false
end

-- A RepeatInterval button mapping becomes Press, in both places the trigger is
-- stored (flag bits 16-19 and bytes 8-11). Returns whether it changed.
local function press(index)
    local x = at(index)
    local flags = live_words[x]
    if bit.band(bit.rshift(flags, 4), 0xf) ~= BUTTON_INPUT or live_words[x + 2] ~= REPEAT_INTERVAL then
        return false
    end
    local value = bit.bor(bit.band(flags, bit.bnot(0xf0000)), bit.lshift(PRESS, 16))
    if value < 0 then value = value + 0x100000000 end -- bit ops are signed 32-bit.
    live_words[x], live_words[x + 2] = value, 0
    return true
end

-- Writes the live record's first count mappings, the rest zeroed, and the
-- count over the game's record at bucket.
local function write_record(bucket, count)
    ffi.fill(live + MAPPINGS_OFFSET + count * MAPPING_SIZE, (MAX_MAPPINGS - count) * MAPPING_SIZE)
    live_words[1] = count
    local record = ffi.cast('MBM_u8 *', bucket)
    ffi.copy(record + MAPPINGS_OFFSET, live + MAPPINGS_OFFSET, MAX_MAPPINGS * MAPPING_SIZE)
    ffi.copy(record + 4, live + 4, 4)
end

-- Keeps the live mappings (all of them, or all but the inherited ones when
-- clean), RepeatInterval buttons turned into Press, and writes the record
-- back if anything changed. Returns how many mappings it removed.
local function compact(bucket, code, clean)
    local count, kept, changed = live_words[1], 0, false
    for index = 0, count - 1 do
        if not (clean and inherited(code, index)) then
            if kept < index then
                ffi.copy(live + MAPPINGS_OFFSET + kept * MAPPING_SIZE, live + MAPPINGS_OFFSET + index * MAPPING_SIZE,
                         MAPPING_SIZE)
            end
            changed = press(kept) or changed
            kept = kept + 1
        end
    end
    if changed or kept < count then write_record(bucket, kept) end
    return count - kept
end

-- Native defaults are not player settings. Capture them before sanitizing,
-- then keep that copy while the game holds our sanitized record. A re-parse
-- supplies a fresh original. Scratch buffers are reused; only the first read
-- of each registered action allocates its private record.
local function prepare_defaults(code)
    local bucket = read_record(DEFAULTS_MAP, state.default_buckets, code, live, live_words)
    if not bucket then return false end
    local found, saved = fingerprint(live_words), originals[code]
    if saved and found == saved.cleaned then return true end
    if not saved then
        saved = {bytes = ffi.new('MBM_u8[?]', RECORD_SIZE)}
        originals[code] = saved
    end
    ffi.copy(saved.bytes, live, RECORD_SIZE)
    saved.fingerprint = found
    ffi.copy(shipped, live, RECORD_SIZE)
    compact(bucket, code, true)
    saved.cleaned = fingerprint(live_words)
    return true
end

-- A fixed slot whose defaults record could not be read at activation is
-- tried again by each sweep; otherwise this only tests one flag.
local function retry_keyboard_defaults()
    if state.keyboard_pending then add_keyboard_defaults() end
end

-- Safe while a binding page is open: only its reset source changes, never the
-- live mappings being captured or the sweep's page/provenance bookkeeping.
local function sanitize_defaults()
    state.defaults_pending = false
    local ready = true
    for _, record in ipairs(state.order) do
        record.defaults_ready = prepare_defaults(record.code)
        ready = record.defaults_ready and ready
    end
    return ready
end

-- What the sweep does with an action this time: nothing (the list is as the
-- sweep left it), clear it, clean it the first time, a restored list, or a
-- list the player changed.
local CLEAR, FIRST, RESTORED, CHANGED = 1, 2, 3, 4

-- The plan for a binding's action, and for a restored list whether a single
-- capture could have made it (one mapping, not RepeatInterval).
local function plan(book, record)
    local code = record.code
    if not record.defaults_ready then return nil, nil, false end
    if not read_record(BINDING_MAP, state.buckets, code, live, live_words) then return nil, nil, false end
    local action = book.actions[code]
    if not action then return FIRST end
    if action.clear then return CLEAR end
    local list = fingerprint(live_words)
    if list == action.left then
        state.swept_counts[code] = live_words[1]
        return nil
    end
    if list == action.found or list == originals[code].fingerprint then
        return RESTORED, live_words[1] == 1 and live_words[at(0) + 2] ~= REPEAT_INTERVAL
    end
    return CHANGED
end

-- Records what the sweep left: after the first clean or a clear, the session
-- and the list found too.
local function remember(book, code, step, found)
    local left, action = fingerprint(live_words), book.actions[code]
    if step == FIRST or step == CLEAR then
        book.actions[code] = {cleared = book.session, found = found, left = left}
        book.dirty = true
    elseif action.left ~= left then
        action.left, book.dirty = left, true
    end
end

-- Carries out a binding's plan; wholesale says restored lists are restores.
-- Returns how many mappings it removed.
local function apply(book, record, wholesale)
    local code, step = record.code, record.plan
    local bucket = read_record(BINDING_MAP, state.buckets, code, live, live_words)
    if not bucket then return nil end
    local found, removed = fingerprint(live_words), 0
    if step == CLEAR then
        removed = live_words[1]
        write_record(bucket, 0)
    else
        local clean = step == FIRST or step == RESTORED and wholesale
        if clean then ffi.copy(shipped, originals[code].bytes, RECORD_SIZE) end
        if step == RESTORED and not wholesale then
            note('Kept the single mapping chosen for ' .. record.id .. ' on a binding page, although it ' ..
                 'equals a developer default.')
        end
        removed = compact(bucket, code, clean)
    end
    remember(book, code, step, found)
    state.swept_counts[code] = live_words[1]
    return removed
end

-- Sweeps the actions of the bindings registered this session (see the top of
-- this file). Restored lists are restores unless a binding page closed since
-- the last sweep and the only restored list is one a single capture can make.
local function sweep_bindings()
    retry_keyboard_defaults()
    -- A failed read cannot consume the binding-page visit: it still explains
    -- a deliberate single-key capture when the next sweep can read its data.
    if not sanitize_defaults() then return end
    local book = load_assignments()
    local restored, wholesale = 0, not state.page_visited
    for _, record in ipairs(state.order) do
        local step, single, readable = plan(book, record)
        if readable == false then return end
        record.plan = step
        if step == RESTORED then
            restored = restored + 1
            wholesale = wholesale or not single
        end
    end
    wholesale = wholesale or restored > 1
    local removed, complete = 0, true
    for _, record in ipairs(state.order) do
        if record.plan then
            local count = apply(book, record, wholesale)
            complete = count ~= nil and complete
            removed = removed + (count or 0)
        end
        record.plan = nil
    end
    if complete then state.page_visited = false end
    if removed > 0 then note('Removed ' .. removed .. ' inherited developer mappings.') end
end

mbm.sweep_bindings = sweep_bindings
mbm.sanitize_defaults = sanitize_defaults
mbm.add_keyboard_defaults = add_keyboard_defaults
end
-- Native bindings-page extension for Steam build 26088801.
if rawget(_G, 'ModBindingsMenu') then return end
local ffi = require('ffi')
local bit = require('bit')
-- Texts and translations: mbm_text = {module = src/bingus_text.lua, locales =
-- locales/}; the other source files: mbm_files.<name> = src/<name>.lua as a
-- function, each run once below: Mod Bindings Menu's own with the shared table
-- mbm, Bingus Shared Runtime's vendored copies (bingus_runtime.lua,
-- bingus_memory.lua) without arguments, returning their tables. The build
-- places both ahead of this file as locals (tests provide them as globals).
local translation = {T = mbm_text.module}
-- Bingus Shared Runtime: the update guard (the family's update-chain policy) and
-- the module hashes every mod shares, read once per session.
local runtime = mbm_files.bingus_runtime()
local memory = mbm_files.bingus_memory().new(runtime)
