translation.tr = translation.T.new(mbm_text.locales.en, mbm_text.locales.bundled,
                                   function(message) note('Text: ' .. message) end)

local GAME_SHA256 = '6D1D4D3BC6FC84801D9F8F1B310E13A603D07409F3D9495D74B42E1D0BB1C08F'
